INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000001', 'DM0001', 'GTN.1.1', 'Định vị được nguồn phát ra âm thanh bằng cách quay về phía phát ra âm thanh đó.', 'Quay đầu và di chuyển ánh mắt để thể hiện nhận thức về âm thanh.', 1, 1),
  ('GL000002', 'DM0001', 'GTN.1.2', 'Nhìn về phía phát ra những âm thanh vui nhộn (tiếng ồn bằng môi (raspberry noise), còi).', 'Trẻ trở nên tích cực hơn, quay đầu và di chuyển ánh mắt, nhìn về người chơi cùng để thể hiện nhận thức về âm thanh.', 2, 1),
  ('GL000003', 'DM0001', 'GTN.1.3', 'Phản ứng lại với giọng nói bằng cách quay về phía người nói.', 'Quay đầu và nhìn vào người nói để thể hiện nhận thức về giọng nói bằng cách', 3, 1),
  ('GL000004', 'DM0001', 'GTN.1.4', 'Nhìn vào tranh trong sách khi người lớn chỉ tay vào đó.', 'Dùng ánh mắt +/- cử chỉ (ví dụ: chạm vào bức tranh) để dõi theo tay chỉ của người lớn vào bức tranh.', 4, 1),
  ('GL000005', 'DM0001', 'GTN.1.5', 'Dõi theo hướng tay chỉ vào cự ly gần (trong tầm với của trẻ) và đặt đồ vật vào trong hộp chứa, các miếng ghép vào bảng ghép,…', 'Đáp ứng với việc người lớn hướng tay chỉ vào cự ly gần bằng cách nhìn và đặt đồ vật ở chỗ đã được chỉ định', 5, 1),
  ('GL000006', 'DM0001', 'GTN.1.6', 'Nhìn vào đồ vật khi người lớn đưa đồ vật đó ra và nói: “(tên trẻ), nhìn này”', 'Di chuyển ánh mắt và quay đầu và nhìn theo hướng đồ vật', 6, 1),
  ('GL000007', 'DM0001', 'GTN.1.7', 'Nhìn vào đối tác khi được gọi tên', 'Di chuyển ánh mắt và quay đầu về phía cơ thể của đối tác', 7, 1),
  ('GL000008', 'DM0001', 'GTN.1.8', 'Dõi theo hướng chỉ tay vào đồ vật hoặc vị trí ở phạm vi gần', 'Phản ứng lại với việc chỉ tay ở khoảng cách gần bằng cách quay đầu hướng về đồ vật hoặc vị trí nào đó', 8, 1),
  ('GL000009', 'DM0001', 'GTN.1.9', 'Dõi theo hướng tay chỉ ở địa điểm xa để lấy đồ chơi', 'Phản ứng với việc chỉ tay ở xa bằng cách tiếp cận và cầm đồ chơi lên', 9, 1),
  ('GL000010', 'DM0001', 'GTN.1.10', 'Nhìn, với tay hoặc mỉm cười đáp lại cử chỉ/điệu bộ và giọng nói của người lớn trong các trò chơi xã hội', 'Tham gia và phản ứng lại với một hoặc nhiều lần chơi các trò chơi xã hội gồm: “ú òa”, “các ngón tay cù”, “cù nhột” …', 10, 1),
  ('GL000011', 'DM0001', 'GTN.1.11', 'Nhìn, với tay, mỉm cười và/hoặc có cử chỉ, điệu bộ phản ứng lại với ngôn ngữ/điệu bộ cử chỉ của người lớn trong bài hát', 'Tương tự như trên. Tham gia và phản ứng lại với một hoặc nhiều câu trong bài hát.', 11, 1),
  ('GL000012', 'DM0001', 'GTN.1.12', 'Phản ứng dừng hoạt động ngay hoặc dừng trong giây lát khi có hiệu lệnh: “không”, “dừng lại”', 'Dừng một hành động đang diễn ra khi có ai đó nói “không, dừng lại”, hoặc thể hiện nhận thức bằng cách dừng tạm thời, quay đầu và nhìn vào người lớn, hoặc thể hiện sự khó chịu (ví dụ: khóc)', 12, 1),
  ('GL000013', 'DM0001', 'GTN.1.13', 'Đặt đồ vật vào tay người lớn khi được yêu cầu bằng lời, đồng thời người lớn xòe tay ta.', 'Phản ứng lại với cử chỉ/điệu bộ hoặc lời nói của người lớn bằng cách đặt hoặc cố gắng đặt đồ vật vào tay người lớn', 13, 1),
  ('GL000014', 'DM0001', 'GTN.1.14', 'Thực hiện những hành động quen thuộc hàng ngày có 1 bước khi được yêu cầu bằng lời nói hoặc gợi ý bằng điệu bộ cử chỉ (ví dụ: “ngồi xuống”, “lại đây”, “làm sạch” …)', 'Thể hiện hành động khi có tín hiệu về lời nói/cử chỉ/điệu bộ. Để qua được thì tối thiểu ở cơ hội đầu tiên cần có 5 hành động. Các ví dụ bao gồm người lớn lặp lại hướng dẫn, sử dụng các cử chỉ/điệu bộ để nhấn mạnh hành động (ví dụ: đập vào ghế để ngồi xuống, cầm xô để rửa) hoặc nhắc trẻ một phần nào đó trong suốt hành động', 14, 1),
  ('GL000015', 'DM0001', 'GTN.1.15', 'Thực hiện những hành động quen thuộc hàng ngày có 1 bước khi được yêu cầu bằng lời nói không gợi ý bằng điệu bộ cử chỉ (ví dụ: “ngồi xuống”, “lại đây”, “làm sạch” …)', 'Hoàn thành hướng dẫn bằng cách thể hiện hành động mà không cần có cử chỉ/điệu bộ hoặc sự hướng dẫn về mặt thể chất của người lớn. Người lớn có thể nhắc lại yêu cầu lần thứ hai mà không cần có cử chỉ/điệu bộ', 15, 1),
  ('GL000016', 'DM0002', 'GTD.1.1', 'Với tay có mục đích/với tay tới mục tiêu để yêu cầu', 'Với đồ vật mong muốn trong tay người lớn để thể hiện yêu cầu. Cử chỉ/điệu bộ này không đi kèm với giao tiếp mắt hoặc các từ/lời nói. Không bao gồm việc trẻ với tới chỉ để chộp', 1, 1),
  ('GL000017', 'DM0002', 'GTD.1.2', 'Phát ra âm có mục đích', 'Phát âm đi kèm với giao tiếp mắt và/hoặc cử chỉ/điệu bộ (ví dụ: với tới) để yêu cầu đồ vật hoặc điều mong muốn', 2, 1),
  ('GL000018', 'DM0002', 'GTD.1.3', '“Yêu cầu” sự giúp đỡ bằng cách đưa đồ vật cho người lớn', 'Yêu cầu giúp đỡ bằng cách đặt đồ vật vào tay người lớn, phát âm hoặc nhìn vào người lớn. Cử chỉ/điệu bộ không đi kèm giao tiếp mắt hoặc phát âm/từ.', 3, 1),
  ('GL000019', 'DM0002', 'GTD.1.4', 'Phát âm theo lượt với đối tác giao tiếp', 'Bập bẹ và/hoặc phát âm kèm giao tiếp mắt tối thiểu ở hai lượt.', 4, 1),
  ('GL000020', 'DM0002', 'GTD.1.5', 'Thế hiện sự từ chối bằng cách đẩy đồ vật ra xa hoặc đưa đồ vật lại cho một người khác', 'Trẻ chỉ cần thực hiện cử chỉ/điệu bộ, không cần đi kèm với giao tiếp mắt hoặc dùng lời nói/từ. Khen ngợi trẻ nếu trẻ thực hiện các cử chỉ/điệu bộ khác (lắc đầu, trẻ thực hiện điệu bộ thể hiện “mọi thứ đã xong xuôi”) hoặc nói (“không”)', 5, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000021', 'DM0002', 'GTD.1.6', 'Chỉ tay để yêu cầu đồ vật mong muốn ở gần', 'Chạm hoặc chỉ vào đồ vật trong khoảng cách 15 – 30 cm bằng ngón trỏ (không phải bằng cả bàn tay) để thể hiện yêu cầu. Đồ vật có thể ở trong tay người lớn hoặc trong tầm với của trẻ.', 6, 1),
  ('GL000022', 'DM0002', 'GTD.1.7', 'Giao tiếp mắt để có được đồ vật mong muốn khi người lớn ngăn trẻ tiếp cận đồ vật/giữ lại đồ vật đó', 'Quay đầu nhìn về phía người lớn và giao tiếp mắt trong 1 – 2 giây +/- cử chỉ/điệu bộ (ví dụ: với, nắm lấy) để yêu cầu đồ vật. Giao tiếp mắt và cử chỉ/điệu bộ không cần đi kèm phát âm/lời nói.', 7, 1),
  ('GL000023', 'DM0002', 'GTD.1.8', 'Chỉ tay để chọn lựa giữa 2 đồ vật', 'Người lớn mỗi tay cầm 1 đồ vật. Trẻ chạm hoặc chỉ về phía đồ vật mong muốn bằng ngón trỏ (không mở lòng bàn tay). Cử chỉ/điệu bộ không cần đi kèm giao tiếp mắt hoặc phát âm/lời nói.', 8, 1),
  ('GL000024', 'DM0002', 'GTD.1.9', 'Kết hợp phát âm và ánh mắt để thể hiện yêu cầu', 'Quay đầu và mắt, nhìn người lớn, giao tiếp mắt (1 – 2 giây) kèm theo phát âm để yêu cầu thứ mong muốn. Phát âm có thể chỉ là từ tương đương. Các ví dụ gồm “ahh” cho ball (bóng) hoặc “ooh” cho go (đi).', 9, 1),
  ('GL000025', 'DM0002', 'GTD.1.10', 'Chỉ tay để yêu cầu đồ vật mong muốn ở xa', 'Sử dụng ngón trỏ (không mở lòng bàn tay) để chỉ về hướng đồ vật mong muốn, cách >90 cm hoặc xa hơn', 10, 1),
  ('GL000026', 'DM0002', 'GTD.1.11', 'Chỉ tay để chọn lựa giữa 2 đồ vật ở xa', 'Người lớn mỗi tay cầm 1 đồ vật nhưng ngoài tầm với của trẻ và chỉ cho trẻ thấy cũng như gọi tên từng đồ vật cho trẻ. Trẻ chỉ về hướng đồ vật mong muốn bằng ngón trỏ (không mở lòng bàn tay). Cử chỉ/điệu bộ không cần đi kèm giao tiếp mắt hoặc phát âm.', 11, 1),
  ('GL000027', 'DM0002', 'GTD.1.12', 'Phát âm theo kiểu bập bẹ (không nhất thiết phải tương đương như từ)', 'Các ví dụ gồm “ba-ba”, “ma-ma”. Phát âm không cần đi kèm giao tiếp mắt hoặc cử chỉ/điệu bộ.', 12, 1),
  ('GL000028', 'DM0002', 'GTD.1.13', 'Phát âm một cách tự phát 5 phụ âm hoặc nhiều hơn', 'Phát âm kèm hoặc không người lớn làm mẫu. Những trò chơi phát âm cũng được tính.', 13, 1),
  ('GL000029', 'DM0002', 'GTD.1.14', 'Phát nhiều âm bập bẹ theo các cách khác nhau/đa dạng', 'Các ví dụ gồm “ba-bu”, “ma-wa” và chuỗi biệt ngữ (theo cách riêng của từng trẻ)', 14, 1),
  ('GL000030', 'DM0003', 'XH.1.1', 'Trẻ tiếp nhận các hoạt động/trò chơi giác quan - xã hội ngắn và sự động chạm', 'Trẻ không thể hiện sự trốn tránh, rút lui hoặc phản ứng tiêu cực', 1, 1),
  ('GL000031', 'DM0003', 'XH.1.2', 'Trẻ dùng cách nhắc/gợi ý bằng thể chất để khởi xướng hoặc tiếp tục (một) thói quen giác quan xã hội', 'Các ví dụ về nhắc thể chất gồm: với tới, bắt chước chuyển động của người lớn, cầm đưa một vật cho người lớn. Nhắc nhở thể chất không cần đi kèm giao tiếp mắt.', 2, 1),
  ('GL000032', 'DM0003', 'XH.1.3', 'Có sự giao tiếp mắt ngắn (2 giây) với một người khác', 'Tham gia bằng cách nhìn và duy trì giao tiếp mắt với một người khác trong 2 giây', 3, 1),
  ('GL000033', 'DM0003', 'XH.1.4', 'Duy trì việc tham gia vào các thói quen giác quan xã hội trong 2 phút', 'Thể hiện sự quan tâm đến thói quen giác quan xã hội bằng cách tiếp cận, quan sát, hoặc tham gia tích cực và yêu cầu sự tiếp tục thông qua giao tiếp mắt, cử chỉ/điệu bộ (ví dụ: với tới, bắt chước chuyển động của người lớn), hoặc phát âm.', 4, 1),
  ('GL000034', 'DM0003', 'XH.1.5', 'Phản ứng lại đối với những đồ vật/hoạt động yêu thích bằng ánh nhìn, với tay, mỉm cười và chuyển động', 'Phản ứng không cần đi kèm với giao tiếp mắt', 5, 1),
  ('GL000035', 'DM0003', 'XH.1.6', 'Nhìn và bắt chước người lớn trong suốt các hoạt động chơi song song với đồ vật', 'Thể hiện sự quan tâm vào hoạt động bằng cách quan sát và bắt chước hành động chơi của người lớn và tiếp tục trò chơi bằng cách bắt chước.', 6, 1),
  ('GL000036', 'DM0003', 'XH.1.7', 'Thể hiện được trong 5 – 10 trò chơi về giác quan xã hội', 'Trong một trò chơi, trẻ có tham gia vào 2 hoặc nhiều lần, bằng bất kỳ hành vi nào đó (với tới, bắt chước, phát âm). Nếu chỉ giao tiếp mắt và cười thôi là chưa đủ. Các ví dụ gồm “Ú òa”, đọc thơ/hát (“Eensy-Weensy Spider”, “If you’re happy and you know it”), các trò chơi (“đi vòng quanh”, “đập bánh”), chơi thổi bong bóng, bóng bay, sách, máy bay,…', 7, 1),
  ('GL000037', 'DM0003', 'XH.1.9', 'Phản ứng với lời chào bằng cách nhìn, quay lại,…', 'Thể hiện nhận thức về lời chào bằng cách quay đầu, thân người và nhìn vào người lớn trong 2 – 3 giây. Phản ứng không cần đi kèm cử chỉ/điệu bộ hoặc phát âm.', 9, 1),
  ('GL000038', 'DM0003', 'XH.1.10', 'Phản ứng lại với lời chào bằng cách thể hiện điệu bộ cử chỉ hoặc phát âm', 'Thể hiện nhận thức về lời chào bằng cách quay đầu, thân người và vẫy tay hoặc phát âm “Chào/tạm biệt” kèm giao tiếp mắt trong 2 – 3 giây.', 10, 1),
  ('GL000039', 'DM0003', 'XH.1.12', 'Cười với đối tác trong khi cùng/phối hợp chơi', 'Cười kèm giao tiếp mắt trong 2 – 3 giây trong suốt hoạt động chơi với người lớn', 12, 1),
  ('GL000040', 'DM0004', 'BC.1.1', 'Bắt chước 8 – 10 hành động có 1 bước với đồ vật (trong vòng 5 giây theo mẫu)', 'Bắt chước 8 hoặc nhiều hơn các hành động với đồ vật trong vòng 5 giây tiếp theo mẫu của người lớn. Các ví dụ gồm đập hai đồ vật với nhau, đặt một vật vào trong hộp chứa, hoặc lăn tròn một đồ vật', 1, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000041', 'DM0004', 'BC.1.2', 'Bắt chước 10 hành động vận động thể chất được nhìn thấy trong bài hát/trò chơi quen thuộc', 'Bắt chước 10 hành động khác nhau trong vòng 5 giây theo mẫu người lớn. Bắt chước hai hành động khác nhau ở mỗi bài hát và 4 – 5 thói quen khác nhau (ví dụ: “5 con khỉ nhỏ”, “nhện giăng tơ”) các trò chơi vận động (ví dụ: “bơi thuyền”, “đi vòng quanh”) hoặc các thói quen chơi khác (ví dụ: ú òa)', 2, 1),
  ('GL000042', 'DM0004', 'BC.1.3', 'Bắt chước 6 hành động vận động ở đầu và khuôn mặt trong bài hát/trò chơi quen thuộc (không nhìn thấy khi thực hiện)', 'Bắt chước 6 hành động khác nhau mà trẻ không thể nhìn thấy bản thân nó khi thực hiện. Ví dụ: đặt tay lên đầu, tai hoặc vỗ má', 3, 1),
  ('GL000043', 'DM0004', 'BC.1.4', 'Bắt chước 6 chuyển động miệng – mặt', 'Bắt chước chuyển động miệng – mặt trong 5 giây theo mẫu của người lớn. Các ví dụ gồm ngọ nguậy lưỡi, thổi trề môi hoặc phồng má thổi phù phù', 4, 1),
  ('GL000044', 'DM0005', 'NT.1.1', 'Xếp/phân loại các vật giống nhau (tối thiểu 5 loại đồ vật)', 'Có thể trong phản ứng với giọng nói của người lớn (ví dụ: “đặt ở đây”) hoặc các tín hiệu về mặt thể chất (ví dụ: chuyền tay nọ sang tay kia) với vài lần thử đầu tiên, nhưng trẻ cần hoàn thiện việc tự xếp/phân loại với tối thiểu là 5 loại đồ vật khác nhau. Các ví dụ gồm xếp/phân loại đoàn tàu, xe ô tô, bút màu và giấy, hoặc que và hình tròn vào các hộp chứa riêng biệt', 1, 1),
  ('GL000045', 'DM0005', 'NT.12', 'Xếp/phân loại các bức tranh giống nhau (tối thiểu 5 tranh khác nhau)', 'Có thể trong phản ứng với giọng nói của người lớn (ví dụ: “đặt ở đây”) hoặc tín hiệu về mặt thể chất (ví dụ: chuyền tay nọ sang tay kia) với vài lần thử đầu tiên, nhưng trẻ cần tự hoàn thành việc xếp/phân loại với tối thiểu là 5 tranh khác nhau', 2, 1),
  ('GL000046', 'DM0005', 'NT.1.2', 'Ghép/phân loại tranh tương ứng với đồ vật (tối thiểu 5 cặp tranh/vật)', 'Có thể trong phản ứng với giọng nói của người lớn (ví dụ: “đặt ở đây”) hoặc tín hiệu về mặt thể chất (ví dụ: chuyền tay nọ sang tay kia) với vài lần thử đầu tiên, nhưng trẻ cần tự hoàn thành việc ghép/phân loại với tối thiểu 5 cặp vật/tranh khác nhau', 3, 1),
  ('GL000047', 'DM0005', 'NT.13', 'Xếp/phân loại vật theo màu sắc (tối thiểu 5 màu)', 'Xếp/phân loại 5 màu hoặc nhiều hơn. Có thể trong phản ứng với giọng nói của người lớn (ví dụ: “đặt ở đây”) hoặc tín hiệu về mặt thể chất (ví dụ: chuyền tay nọ sang tay kia) với vài lần thử đầu tiên, nhưng trẻ cần tự hoàn thành việc xếp/phân loại. Các ví dụ gồm ghép/phân loại các khối gỗ màu đỏ và màu xanh da trời, màu cam và màu xanh lá cây, hoặc các quả bóng màu vàng và màu tím vào các hộp chứa riêng biệt', 4, 1),
  ('GL000048', 'DM0006', 'C.1.1', 'Có hành vi phù hợp với các đặc tính của 5 đồ vật khác nhau', 'Trẻ cần khởi xướng hành động không phải trong phản ứng lại với người lớn. Hành vi cần phù hợp với đặc tính của đồ vật. Các ví dụ gồm gõ búa, lăn hoặc nảy bóng hay thả khối', 1, 1),
  ('GL000049', 'DM0006', 'C1.2', 'Chơi độc lập và phù hợp với 10 đồ chơi chỉ cần 1 hành động chơi (cách chơi linh hoạt, không hạn chế hoặc lặp đi lặp lại)', 'Chơi phù hợp với thang phát triển (ví dụ: không hạn chế hoặc không lặp đi lặp lại), liên quan đến đồ vật/hành động, và bao gồm các hành động chỉ có 1 bước. Các ví dụ gồm đặt các khối trong một hộp sắp xếp, đế bóng vào đường zíc zắc, đóng cọc vào lỗ hoặc tách rời các hạt', 2, 1),
  ('GL000050', 'DM0006', 'C.1.2', 'Chơi độc lập với đồ chơi yêu cầu sự lặp lại cùng hành động tương tự ở trên đồ vật có số lượng nhiều (thả vòng, lồng cốc)', 'Chơi bao gồm việc hoan thành một cách độc lập hoạt động/đồ vật. Vượt qua với 5 đồ chơi hoặc nhiều hơn. Các ví dụ gồm đặt vòng vào hộp thả, xếp lồng cốc hoặc lấy cốc ra, thả hình khối hoặc đóng cọc vào lỗ.', 3, 1),
  ('GL000051', 'DM0006', 'C1.3', 'Chứng tỏ hành vi chơi phù hợp với rất nhiều đồ chơi ở tuổi của trẻ chỉ cần 1 hành động chơi: ném bóng, thả hình khối, gõ chốt vào lỗ, lăn xe ô tô (đồ chơi phù hợp với cả khả năng di chuyển, vận động của trẻ)', 'Chơi với đồ vật/hoạt động chỉ cần hành động một bước. Vượt qua với 8 – 10 đồ chơi dành cho lứa tuổi của trẻ. Ví dụ: các trò chơi ném bóng, lăn xe ô tô hoặc đánh trống', 4, 1),
  ('GL000052', 'DM0006', 'C.1.3', 'Chơi độc lập với những đồ chơi yêu cầu 2 hành động khác nhau (ví dụ: lấy ra, cho vào)', 'Chơi hoàn thành một cách độc lập với đồ vật/hoạt động. Vượt qua với 8 – 10 đồ chơi. Các ví dụ gồm thả/lấy khối gỗ ra khỏi hộp chứa, lăn và đập đất nặn ra, hoặc đặt hoặc tách các hạt ra', 5, 1),
  ('GL000053', 'DM0006', 'C1.4', 'Chơi độc lập với những đồ chơi yêu cầu một số hành động khác nhau (cho vào, mở ra, di chuyển, đóng lại)', 'Chơi hoàn thành một cách độc lập với đồ vật/hành động. Vượt qua với 6 – 8 đồ chơi. Các ví dụ gồm mở/đóng các hộp chứa, lấy các đô vật ra/bỏ các đồ vật vào, thực hiện các hành động khác nhau với đồ vật', 6, 1),
  ('GL000054', 'DM0006', 'C.1.4', 'Tự thực hiện những hành động có chủ đích với một loạt đồ vật', 'Các hành động có chủ đích và do bản thân tự định hướng. Có thể trong phản ứng với mẫu của người lớn nhưng thực hiện một cách độc lập, tự phát trong tối thiểu là một hành động. Các ví dụ gồm để điện thoại lên tai, chải đầu bằng lược, cho thìa/dĩa vào miệng, lau mũi bằng khăn giấy, đưa cốc lên môi, nhặt các hạt vào', 7, 1),
  ('GL000055', 'DM0006', 'C1.5', 'Hoàn thành hoạt động chơi và cắt đồ', 'Hoàn thiện một cách phù hợp hoạt động và thể hiện sự nỗ lực thu dọn sạch sẽ (ví dụ: cho đồ vật vào hộp chứa, đưa đồ dùng cho người lớn). Có thể là phản ứng với giọng nói hoặc cử chỉ/điệu bộ của người lớn để bắt đầu thói quen nhưng cần thực hiện mà không cần nhắc nhở về mặt thể chất', 8, 1),
  ('GL000056', 'DM0007', 'VDT.1.1', 'Đặt 1 đến 2 hình dạng vào bảng phân loại hình', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen, nhưng cần tự đặt 1 – 2 hình dạng', 1, 1),
  ('GL000057', 'DM0007', 'VDT.1.2', '(Đồ chơi phân loại hình khối: tam giác, hình vuông,…)', NULL, 2, 1),
  ('GL000058', 'DM0007', 'VDT.1.3', 'Đặt các vòng tròn vào cột xếp vòng', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen, nhưng cần tự đặt được 3 vòng tròn hoặc nhiều hơn', 3, 1),
  ('GL000059', 'DM0007', 'VDT.1.4', 'Hoàn thành 3 miếng ghép hình có núm cầm tay trong bảng ghép hình gỗ', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen, nhưng cần tự đặt được 3 miếng ghép hoặc nhiều hơn', 4, 1),
  ('GL000060', 'DM0007', 'VDT.1.5', 'Đút các khối hình dạng cây nấm vào bảng (pegboard)', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen, nhưng cần tự đút được 3 hình khối hoặc nhiều hơn', 5, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000061', 'DM0007', 'VDT.1.6', 'Ấn các nút của 5 loại đồ chơi nguyên nhân – kết quả khác nhau', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần tự ấn được nút', 6, 1),
  ('GL000062', 'DM0007', 'VDT.1.7', 'Tách rời các hạt (dạng chuỗi hoặc dạng Lego)', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần tự lấy ra được 3 hạt/khối hình Lego hoặc nhiều hơn', 7, 1),
  ('GL000063', 'DM0007', 'VDT.1.8', 'Sử dụng 2 ngón và 3 ngón để cầm những đồ chơi phù hợp', 'Người lớn của thể đặt đồ chơi trong tầm với của trẻ nhưng không hỗ trợ gì', 8, 1),
  ('GL000064', 'DM0007', 'VDT.1.9', 'Xếp chồng 3 khối lớn thành một ngọn tháp (hoặc chồng các cốc)', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần tự chồng được tối thiểu là 3 khối/cốc', 9, 1),
  ('GL000065', 'DM0007', 'VDT.1.10', 'Tạo dấu, các đường kẻ, chữ viết nguệch ngoạc và các dấu chấm bằng bút dấu/bút sáp màu', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần tự cầm và tạo dấu được. Dấu không cần theo mẫu được nhận dạng', 10, 1),
  ('GL000066', 'DM0007', 'VDT.1.11', 'Đập búa đồ chơi vào bóng, chốt, …', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần tự cầm nắm và đập được đồ chơi', 11, 1),
  ('GL000067', 'DM0007', 'VDT.1.12', 'Xúc/cào/rót cát, nước, gạo, …', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần cầm được đồ vật và xúc/cào rót một cách độc lập', 12, 1),
  ('GL000068', 'DM0007', 'VDT.1.13', 'Xếp chồng các hình khối Lego to', 'Có thể trong phản ứng lại với tín hiệu của người lớn đế bắt đầu thói quen nhưng cần xếp chồng được tối thiểu là 3 Lego một cách độc lập', 13, 1),
  ('GL000069', 'DM0008', 'VDTH.1.1', 'Đá quả bóng to', 'Có thể không vịn vào người lớn hoặc đồ vật (bàn, ghế) để đá bóng. Duy trì được thăng bằng; không ngã; có thể có dáng điệu kỳ quặc', 1, 1),
  ('GL000070', 'DM0008', 'VDTH.1.2', 'Lên xuống cầu thang có hỗ trợ, hai chân không luân phiên', 'Có thể vịn vào rào hoặc tay người lớn, đặt cả hai chân vào một bậc. Có thể không để tay hoặc đầu gối xuống các bậc', 2, 1),
  ('GL000071', 'DM0008', 'VDTH.1.3', 'Trèo từ 1 – 2 bước lên cầu thang nhỏ để trượt', 'Có thể thực hiện mà không cần giúp đỡ', 3, 1),
  ('GL000072', 'DM0008', 'VDTH.1.4', 'Trèo lên và xuống các dụng cụ chơi lớn', 'Có thể thực hiện mà không cần giúp đỡ. Các ví dụ gồm xe đạp, ngựa cưỡi, ghế lắc dành cho trẻ con hoặc người lớn', 4, 1),
  ('GL000073', 'DM0008', 'VDTH.1.5', 'Tự bảo vệ khi bị mất thăng bằng', 'Sử dụng các phản ứng tự bảo vệ hoặc giữ thăng bằng (ví dụ: chống tay xuống, vươn tay ra, bảo vệ đầu)', 5, 1),
  ('GL000074', 'DM0008', 'VDTH.1.6', 'Đi xung quanh đồ vật trên sàn chứ không bước lên chúng', 'Thể hiện nhận thức về cơ thể trong mối tương quan với đồ vật bằng cách bước qua hoặc đi quanh đồ vật', 6, 1),
  ('GL000075', 'DM0008', 'VDTH.1.7', 'Ném bóng và túi hạt theo bất kì hướng nào', 'Có thể thực hiện mà không cần giúp đỡ và có lực đẩy về trước', 7, 1),
  ('GL000076', 'DM0008', 'VDTH.1.8', 'Lăn bóng qua lại với một người khác (tối thiểu 2 vòng)', 'Người lớn có thể bắt đầu thói quen nhưng trẻ thể hiện sự quan tâm bằng cách lăn bóng về hướng người lớn', 8, 1),
  ('GL000077', 'DM0009', 'HV.1.1', 'Thể hiện tối thiểu những hành vi có vấn đề', 'Các ví dụ gồm hành vi tự làm đau bản thân, hung hăng, các triệu chứng ở mức độ thường xuyên và/hoặc nghiêm trọng', 1, 1),
  ('GL000078', 'DM0009', 'HV.1.2', 'Ngồi trên ghế hoặc đối mặt với người lớn trong các hoạt động vui nhộn mà không có khó khăn gì trong 1 – 2 phút', 'Ngồi yên/thoải mái trong tối thiểu là 60 giây trong khi tương tác với người lớn', 2, 1),
  ('GL000079', 'DM0009', 'HV.1.3', 'Sẵn lòng tham gia vào những trò chơi đơn giản trên ghế và trên sàn với người lớn trong 5 phút', 'Các trò chơi có thể gồm “Ú òa”, bài hát hoặc các thói quen vận động (ví dụ: cù, nâng lên/hạ xuống vạt áo của người lớn)', 3, 1),
  ('GL000080', 'DM0009', 'HV.1.4', 'Để người lớn tiếp cận và tương tác (người lớn hạn chế tối thiểu yêu cầu) mà không có vấn đề hành vi trong khoảng 20 phút', 'Các yêu cầu của người lớn nằm trong khả năng hiện tại của trẻ. Có thể gây ồn ào, nhặng xị nhưng không có hành vi hung hăng', 4, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000081', 'DM0009', 'HV.1.5', 'Tương tác một cách phù hợp với các thành viên gia đình (Ví dụ: không hung hăng hoặc có những tương tác không phù hợp)', 'Không hung hăng hoặc không có tương tác không phù hợp theo như quan sát trong báo cáo của phụ huynh', 5, 1),
  ('GL000082', 'DM0010', 'TL.1.1', 'Ăn đồ ăn chính và đồ ăn nhẹ (phụ) tại bàn', 'Ngồi tại bàn suốt bữa ăn (Ví dụ: không đứng dậy hoặc đi khỏi bàn trong bữa ăn; không cần ngồi trong suốt bữa ăn của gia đình)', 1, 1),
  ('GL000083', 'DM0010', 'TL.1.2', 'Ăn bữa chính một cách độc lập', 'Người lớn dọn đồ ăn ra nhưng không trợ giúp gì khác', 2, 1),
  ('GL000084', 'DM0010', 'TL.1.3', 'Sử dụng một chiếc cốc không nắp', 'Cầm và đưa cốc lên miệng mà không cần trợ giúp. Có thể đổ một chút khi đang uống', 3, 1),
  ('GL000085', 'DM0010', 'TL.1.4', 'Sử dụng thìa', 'Cầm và đưa thìa lên miệng mà không cần trợ giúp cho hầu hết các lần cắn vào. Thỉnh thoảng có đổ một chút', 4, 1),
  ('GL000086', 'DM0010', 'TL.1.5', 'Sử dụng dĩa', 'Cầm và đưa dĩa lên miệng mà không cần trợ giúp cho hầu hết các lần cắn vào. Thỉnh thoảng có đổ một chút', 5, 1),
  ('GL000087', 'DM0010', 'TL.1.6', 'Ăn nhiều loại thức ăn và các nhóm đồ ăn khác nhau', 'Báo các của phụ huynh là đủ', 6, 1),
  ('GL000088', 'DM0010', 'TL.1.7', 'Chấp nhận thức ăn mới có trong đĩa (bát)', 'Cho phép thức ăn mới ở trong đữa và có thể cố ăn (ví dụ: chạm, ngửi hoặc cho vào miệng). Không nhất thiết phải ăn.', 7, 1),
  ('GL000089', 'DM0010', 'TL.1.8', 'Uống bằng ống hút', 'Người lớn có thể để ống hút vào miệng trẻ nếu chưa bao giờ trẻ thực hiện', 8, 1),
  ('GL000090', 'DM0011', 'TL.1.9', 'Cởi một phần trang phục có sự hỗ trợ', 'Không cần mở cúc hoặc kéo khóa nhưng có thể cởi bò trang phục (Ví dụ: áo phông, quần đùi, giày, tất) có trợ giúp. Các ví dụ gồm người lớn giúp trẻ kéo tay áo và trẻ kéo áo qua khỏi đầu, người lớn cởi dây giày và trẻ kéo giày ra khỏi chân, hoặc người lớn kéo khóa quần và trẻ tụt nó xuống khỏi chân.', 1, 1),
  ('GL000091', 'DM0011', 'TL.1.10', 'Mặc vào một phần trang phục có sự hỗ trợ', 'Không cần cài cúc hoặc kéo khóa trang phục, nhưng có thể mặc được (ví dụ: áo phông, quần đùi, giày, tất) có trợ giúp. Các ví dụ gồm người lớn kéo áo lên và trẻ thì chui đầu vào, người lớn giữ giầy còn trẻ xỏ vào, hoặc người lớn giúp trẻ cầm quần cho trẻ xỏ vào và kéo lên.', 2, 1),
  ('GL000092', 'DM0012', 'TL.1.11', 'Để tay dưới dòng nước chảy', 'Có thể được gợi ý, nhưng phải để tay được dưới vòi nước trong tối thiểu 5 giây.', 1, 1),
  ('GL000093', 'DM0012', 'TL.1.12', 'Lau khô tay bằng khăn', 'Có thể được gợi ý, nhưng phải sử dụng được khăn lau để lau khô cả hai tay.', 2, 1),
  ('GL000094', 'DM0012', 'TL.1.15', 'Chịu chải tóc, lau mũi và đánh răng', 'Có thể gây ồn ào nhưng người lớn có thể thực hiện thói quen mà không có các vấn đề hành vi hung hăng, tự làm đau bản thân hoặc các hành vi nghiêm trọng', 5, 1),
  ('GL000095', 'DM0012', 'TL.1.16', 'Cho bản chải đánh răng vào miệng', 'Cho bàn chải vào miệng, nếm kem đánh răng. Không cần phải chải răng.', 6, 1),
  ('GL000096', 'DM0013', 'TL.1.17', 'Cho quần áo bẩn vào giỏ', 'Có thể được nhắc nhở hoặc gợi ý (Ví dụ: người lớn cầm quần áo, chỉ vào giỏ) nếu cần thiết, nhưng có thể thả quần áo vào giỏ được', 1, 1),
  ('GL000097', 'DM0013', 'TL.1.18', 'Bỏ rác vào thùng rác', 'Có thể được nhắc nhở hoặc gợi ý (Ví dụ: người lớn cầm khăn giấy, chỉ vào thùng rác) nếu cần thiết, nhưng có thể thả được rác vào thùng rác', 2, 1),
  ('GL000098', 'DM0014', 'GTN.2.1', 'Làm theo các chỉ dẫn “dừng lại” hoặc “chờ đợi” mà không cần nhắc hay ra hiệu cử chỉ/điệu bộ.', 'Trẻ phản ứng lại với hướng dẫn bằng lời; dừng hoàn toàn hoạt động, nhìn vào người lớn và chờ người lớn hướng dẫn.', 1, 1),
  ('GL000099', 'DM0014', 'GTN.2.2', 'Làm theo 8 – 10 hướng dẫn bằng lời để thực hiện hoạt động có một bước bao gồm cả hành động cơ thể và hành động với đồ vật.', 'Trẻ phản ứng lại với những hướng dẫn bằng lời bao gồm các động từ (VD: lắc chùy lắc, đập gậy, ôm bé, đập bột nặn, cắt, đứng dậy, vỗ tay, ngọ nguậy tai; phải theo cả hai hình thức – các hành động của cơ thể và hành động lên đồ vật).', 2, 1),
  ('GL000100', 'DM0014', 'GTN.2.3', 'Nhận biết được các bộ phận cơ thể của mình hoặc của người khác bằng cách chỉ tay hay gọi tên.', 'Đạt yêu cầu khi nhận diện được 5 bộ phận cơ thể hoặc nhiều hơn.', 3, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000101', 'DM0014', 'GTN.2.4', 'Phản ứng lại với hướng dẫn bằng lời yêu cầu đưa/chỉ tay/cho xem 8 – 10 đồ vật cụ thể nào đó trong khi chơi, khi mặc quần áo, khi ăn (VD: em bé, ghế, xe ô tô, khối gỗ, cốc, con gấu).', 'Tự diễn giải.', 4, 1),
  ('GL000102', 'DM0014', 'GTN.2.5', 'Nhận ra được 3 bức tranh trong sách bằng cách chỉ tay hoặc chú ý nhìn (bao gồm: cốc, ô tô, con chó, con mèo, em bé).', 'Phản ứng lại với “… ở đâu?” hoặc “Chỉ cho cô… ?” bằng việc chỉ trỏ bằng ngón trỏ và nhìn.', 5, 1),
  ('GL000103', 'DM0014', 'GTN.2.6', 'Hiểu được các khái niệm về không gian đơn giản (VD: trong, trên).', 'Đạt yêu cầu khi trẻ thể hiện được hiểu biết chung về 3 giới từ hoặc hơn bằng cách làm theo những chỉ dẫn bằng lời trong đó có sử dụng đồ vật.', 6, 1),
  ('GL000104', 'DM0014', 'GTN.2.7', 'Nhìn vào người và ảnh của người đó khi được gọi tên – người thân gia đình, thú cưng, giáo viên.', 'Đạt yêu cầu khi phản ứng lại với 4 tên gọi khác nhau hoặc hơn. Nếu người/vật nuôi có mặt ở đó, trẻ phải nhìn vào người hoặc vật nuôi đó khi tên được gọi (cũng có thể chỉ). Nếu là tranh ảnh, trẻ chạm hoặc chỉ vào bức tranh khi được gọi tên.', 7, 1),
  ('GL000105', 'DM0014', 'GTN.2.8', 'Lấy 8 – 10 đồ vật ở trong phòng nhưng không trực tiếp ở trước mặt trẻ mà cần phải tìm kiếm một chút, theo yêu cầu bằng lời.', 'Khi phản ứng với yêu cầu bằng lời “Lấy…”, trẻ lấy đồ vật trong phòng nhưng ngoài tầm nhìn. Nhiệm vụ bao gồm nhớ được yêu cầu đủ lâu để thực hiện việc tìm kiếm bằng mắt ở trong phòng, và lấy được đồ vật trên sàn, trên bàn, ghế hoặc trên giá.', 8, 1),
  ('GL000106', 'DM0014', 'GTN.2.9', 'Với yêu cầu bằng lời (có kèm cử chỉ/điệu bộ), hoàn thành 2 hành động với 1 đồ vật.', 'Trẻ xâu chuỗi 2 hành động với nhau trên 1 đồ vật đáp lại một hướng dẫn bằng lời kèm cử chỉ/điệu bộ. Cần phải thể hiện được 3 chuỗi hành động khác nhau hoặc nhiều hơn mới đạt yêu cầu (Vd: “Đi kiếm và đem giày của con lại cho cô”).', 9, 1),
  ('GL000107', 'DM0014', 'GTN.2.10', 'Chỉ vào các bộ phận cơ thể được gọi tên ở trong tranh.', 'Nhận diện được 5 bộ phận cơ thể hoặc nhiều hơn trong một bức ảnh lớn hoặc bản vẽ khi được hỏi.', 10, 1),
  ('GL000108', 'DM0015', 'GTD.2.1', 'Sử dụng các kí hiệu riêng hoặc cử chỉ/điệu bộ kèm phát âm để thể hiện (yêu cầu, công việc đã hoàn thành, sự chia sẻ, sự giúp đỡ, sự phản đối).', 'Trẻ kết hợp cử chỉ/điệu bộ đặc biệt và giọng nói hoặc phát âm từ gần đúng (nói không chuẩn) để giao tiếp tất cả 4 chức năng này.', 1, 1),
  ('GL000109', 'DM0015', 'GTD.2.2', 'Phát âm 6 – 10 từ đơn hoặc cố phát âm từ gần đúng trong ngữ cảnh quen thuộc hàng ngày, các thói quen về giác quan – xã hội, các bài hát.', 'Phát âm 5 từ tương đương khác nhau hoặc nhiều hơn trong các thói quen xã hội quen thuộc. Có thể tự phát hoặc bắt chước nhưng không được nhắc.', 2, 1),
  ('GL000110', 'DM0015', 'GTD.2.3', 'Phát âm tự phát các từ có liên quan đến một thói quen chơi nào đó (lăn, đi, dừng).', 'Phát âm 3 từ tương đương khác nhau hoặc nhiều hơn gồm các động từ liên quan đến các hành động cơ thể hoặc tương tác với đồ vật – tự phát hoặc bắt chước nhưng không được nhắc.', 3, 1),
  ('GL000111', 'DM0015', 'GTD.2.4', 'Sử dụng được tối thiểu 20 từ (có thể nói chưa chuẩn hoặc gần đúng), trong đó gồm có danh từ (tên của đồ vật, con vật, người) và những loại từ khác (chẳng hạn như động từ hoặc giới từ: đã xong, lên…).', 'Trẻ tự phát sử dụng từ, dù có thể chưa đúng hoàn toàn, để yêu cầu hoạt động hay đồ vật. Phải dùng được cả danh từ và các loại từ khác mới đạt yêu cầu.', 4, 1),
  ('GL000112', 'DM0015', 'GTD.2.5', 'Gắn tên một cách tự phát cho các đồ vật và tranh ảnh.', 'Đạt yêu cầu nếu trẻ nói được tên của 5 đồ vật hoặc nhiều hơn và 5 bức tranh hoặc nhiều hơn một cách tự phát.', 5, 1),
  ('GL000113', 'DM0015', 'GTD.2.6', 'Phát âm với các ngữ điệu khác nhau trong các bài hát.', 'Trẻ có các ngữ điệu khác nhau khi phát âm một số từ trong bài hát hoặc ngâm nga, thể hiện nhận thức về ngữ điệu trong đó.', 6, 1),
  ('GL000114', 'DM0015', 'GTD.2.7', 'Yêu cầu và từ chối bằng cách sử dụng các từ đơn có kèm ánh nhìn.', 'Trẻ sử dụng các từ đơn với ánh nhìn để truyền tải cả yêu cầu và phản đối, từ chối hoặc phủ nhận.', 7, 1),
  ('GL000115', 'DM0015', 'GTD.2.8', 'Gắn tên cho các hành động trong ngữ cảnh (VD: trong khi di chuyển cơ thể và/hoặc các hành động với các đồ vật).', 'Trẻ phát âm tối thiểu 10 động từ, cả bắt chước lẫn tự phát để gắn tên cho những hành động của bản thân, của người khác hay đối với đồ vật.', 8, 1),
  ('GL000116', 'DM0015', 'GTD.2.9', 'Sử dụng gần đúng tên của 3 người quan trọng (bao gồm cả bản thân).', 'Trẻ sử dụng tên để gọi người trong bức tranh, trong gương và ngoài đời thực hoặc để thu hút sự chú ý của người đó. Có thể trong phản ứng lại với câu hỏi “Ai đó?”.', 9, 1),
  ('GL000117', 'DM0015', 'GTD.2.10', 'Lắc đầu và nói “Không” để từ chối.', 'Trẻ kết hợp một cách tự phát việc lắc đầu kèm nói “Không” để từ chối một lời đề nghị.', 10, 1),
  ('GL000118', 'DM0015', 'GTD.2.11', 'Gật đầu thể hiện ý “có” và nói “Có” để xác nhận.', 'Trẻ kết hợp một cách tự phát việc gật đầu kèm nói “Có” để chấp nhận một đề nghị.', 11, 1),
  ('GL000119', 'DM0015', 'GTD.2.12', 'Hỏi (hoặc tương đương) “Cái gì?” khi bắt gặp cái gì đó lạ.', 'Trẻ nhìn vào người lớn một cách tự phát và cử chỉ/điệu bộ hướng về đồ vật trong khi hỏi “Cái gì đó?” trong vài ngữ cảnh khác nhau.', 12, 1),
  ('GL000120', 'DM0016', 'CYC.2.1', 'Khi người khác yêu cầu “Nhìn…” và đưa đồ vật ra, trẻ phản ứng bằng cách chuyển ánh nhìn, quay người và nhìn vào đồ vật được đưa ra.', 'Tự diễn giải.', 1, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000121', 'DM0016', 'CYC.2.2', 'Phản ứng lại yêu cầu “Nhìn” và chỉ tay bằng cách hướng về phía đồ vật /người được chỉ định ở xa.', 'Tự diễn giải.', 2, 1),
  ('GL000122', 'DM0016', 'CYC.2.3', 'Đưa hoặc lấy đồ vật từ người khác có phối hợp giao tiếp mắt.', 'Việc này gồm việc đưa và nhận. Nếu là nhận, người lớn không nên đưa ngay đồ vật ra. Ánh nhìn thể hiện sự giao tiếp “yêu cầu”.', 3, 1),
  ('GL000123', 'DM0016', 'CYC.2.4', 'Đáp ứng lại với “Cho xem” bằng cách chìa đồ vật cho người lớn.', 'Tự diễn giải.', 4, 1),
  ('GL000124', 'DM0016', 'CYC.2.5', '“Cho người khác xem” đồ vật một cách tự phát.', 'Trẻ biết đưa đồ chơi ra trước mặt người lớn, nhìn vào người lớn và chờ đợi một lời nhận xét. Nếu trẻ tự thể hiện hành vi này vài lần trong một giờ chơi là đạt yêu cầu.', 5, 1),
  ('GL000125', 'DM0016', 'CYC.2.6', 'Dõi theo tay chỉ hoặc ánh nhìn một cách tự phát (không có tín hiệu bằng lời) để nhìn vào đích.', 'Thu hút được ánh nhìn của trẻ trong tương tác mặt đối mặt và sau đó quay ra nhìn đồ vật. Vượt qua nếu trẻ có quay đầu và tìm kiếm một chút. Không cần phải tìm được đích.', 6, 1),
  ('GL000126', 'DM0016', 'CYC.2.7', 'Tự phát chỉ tay vào những đồ vật yêu thích.', 'Trẻ tự thể hiện hành vi này vài lần trong mỗi giờ. Trẻ cần phải chỉ được đích và nhìn vào người lớn rồi chờ đợi lời bình luận thì mới đạt yêu cầu.', 7, 1),
  ('GL000127', 'DM0016', 'CYC.2.8', 'Cười với người lớn trong hoạt động với đồ vật yêu thích.', 'Trẻ đưa ánh mắt nhìn từ đồ vật sang mắt người lớn và quay trở lại đồ vật để chia sẻ niềm vui. Cần phải thấy vài lần trong thời gian 10 phút của trò chơi xã hội để đạt yêu cầu.', 8, 1),
  ('GL000128', 'DM0017', 'XH.2.1', 'Khởi xướng và duy trì giao tiếp mắt trong giao tiếp.', 'Trẻ bắt đầu trao đổi giao tiếp (bất kì dạng nào) với ánh nhìn và duy trì ánh nhìn đó theo một cách tự nhiên trong suốt quá trình trao đổi.', 1, 1),
  ('GL000129', 'DM0017', 'XH.2.2', 'Yêu cầu bằng lời hoặc khởi xướng bằng hành động thể chất trong các trò chơi xã hội quen thuộc.', 'Trẻ khởi xướng và đưa ra tín hiệu ánh nhìn khi di chuyển cơ thể, cử chỉ/điệu bộ hoặc giọng nói cụ thể trong một trò chơi nào đó. Để vượt qua, cần phải yêu cầu được 3 trò chơi hoặc nhiều hơn.', 2, 1),
  ('GL000130', 'DM0017', 'XH.2.3', 'Đáp lại những hành vi thể hiện sự yêu mến: ôm, hôn những người thân khác.', 'Trẻ ôm những người lớn quen thuộc một cách tự phát, hôn vào má hoặc môi.', 3, 1),
  ('GL000131', 'DM0017', 'XH.2.4', 'Sử dụng cử chỉ/điệu bộ hoặc các từ để thu hút sự chú ý của người lớn.', 'Trẻ tìm kiếm giao tiếp mắt từ người lớn bằng cách sử dụng từ hoặc cử chỉ/điệu bộ rõ ràng (vẫy tay, chỉ, quay mặt, vỗ nhẹ…).', 4, 1),
  ('GL000132', 'DM0017', 'XH.2.5', 'Đáp lại lời chào “Hi” hoặc tạm biệt “Bai bai” và bắt chước vẫy tay.', 'Trẻ phản ứng lại với lời chào hỏi bằng cả các từ và cử chỉ/điệu bộ không cần nhắc nhở.', 5, 1),
  ('GL000133', 'DM0017', 'XH.2.6', 'Yêu cầu sự giúp đỡ bằng lời hoặc bằng cử chỉ/điệu bộ.', 'Trẻ khởi xướng yêu cầu giúp đỡ bằng cách sử dụng các kí hiệu thông thường/theo quy ước hoặc từ tương đương kết hợp với ánh nhìn. Không tính chuyển động của tay và cơ thể trừ phi đi kèm với cả ánh nhìn và các từ phù hợp.', 6, 1),
  ('GL000134', 'DM0017', 'XH.2.7', 'Kết hợp một cách nhất quán giao tiếp mắt với phát âm và/hoặc cử chỉ/điệu bộ trong giao tiếp trực tiếp.', 'Trẻ kết hợp nhất quán các hành động giao tiếp tự phát với ánh nhìn.', 7, 1),
  ('GL000135', 'DM0017', 'XH.2.8', '“Nhảy” với người khác trong các trò chơi vòng tròn theo nhạc.', 'Trẻ chơi một số trò chơi vòng tròn khác nhau và bắt chước chuyển động nhảy theo nhạc (“Hokey Pokey”, “Chơi vòng quanh”, “Cầu Luân Đôn”).', 8, 1),
  ('GL000136', 'DM0017', 'XH.2.9', 'Chạy với người khác trong trò chơi “đuổi bắt”.', 'Trẻ đuổi theo người khác và bắt được người đó trong trò chơi “đuổi bắt” và cũng chạy khi bị người khác đuổi trong trò chơi đó.', 9, 1),
  ('GL000137', 'DM0017', 'XH.2.10', 'Thu hút sự chú ý giao tiếp của đối tác bằng cách sử dụng tên của người hoặc trò chơi, và khởi xướng trò chơi hoặc hoạt động xã hội.', 'Trẻ khởi xướng một cách tự phát các trò chơi xã hội quen thuộc với một đối tác bằng cách thiết lập giao tiếp mắt và sử dụng cử chỉ/điệu bộ đi kèm tên hoặc một từ chỉ hành động (VD: “cù”, “đuổi”).', 10, 1),
  ('GL000138', 'DM0018', 'XH.2.11', 'Đưa đồ vật cho bạn đồng lứa khi được yêu cầu.', 'Trẻ phản ứng lại một cách nhất quán với yêu cầu bằng lời của bạn cùng lứa cho một đồ vật bằng cách nhìn và đưa nó cho người bạn đó.', 1, 1),
  ('GL000139', 'DM0018', 'XH.2.12', 'Tham gia vào các trò chơi và bài hát quen thuộc trong nhóm.', 'Trẻ tham gia hát một bài quen thuộc và các trò chơi xã hội với mô hình chuyển động phù hợp trong một nhóm nhỏ (1 – 2 trẻ khác) mà không có bất kì tín hiệu đặc biệt nào.', 2, 1),
  ('GL000140', 'DM0018', 'XH.2.13', 'Tiếp tục hoạt động khi có bạn cùng lứa tham gia chơi song song.', 'Trẻ tiếp tục hoạt động khi bạn cùng lứa tham gia vào, hiểu và tiếp nhận sự tham gia của bạn cùng lứa. Trẻ không “giữ” đồ chơi cho riê ng mình hay từ chối sự tiếp cận đó.', 3, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000141', 'DM0018', 'XH.2.14', 'Phản ứng lại một cách phù hợp với sự chào hỏi của bạn cùng lứa.', 'Trẻ phản ứng lại một cách tự phát với “Chào” và “Tạm biệt” từ một người bạn cùng lứa bằng việc nhìn, có cử chỉ/điệu bộ và từ phù hợp.', 4, 1),
  ('GL000142', 'DM0018', 'XH.2.15', 'Chơi lần lượt với bạn cùng lứa trong các hoạt động đơn giản với đồ chơi khi được yêu cầu; đưa và lấy lại.', 'Trong tình huống chơi song song, trẻ phản ứng lại một cách đều đặn với yêu cầu chơi lần lượt của bạn bằng cách đưa đồ vật khi được yêu cầu và yêu cầu chơi khi tới lượt của mình bằng ngôn ngữ hoặc cử chỉ, kết hợp cả với ánh nhìn.', 5, 1),
  ('GL000143', 'DM0018', 'XH.2.16', 'Ngồi trong nhóm với các bạn cùng lứa và tham gia vào các hướng dẫn quen thuộc của người lớn.', 'Trẻ ngồi trong một nhóm nhỏ mà không cần một chỗ đặc biệt nào hoặc sự trợ giúp từ người lớn, tham gia chú ý tới người lớn và làm theo các chỉ dẫn bằng lời trong khả năng của trẻ. Người lớn có thể gọi tên trẻ để chuyển tải chỉ dẫn nhưng không nhắc thêm gì khác.', 6, 1),
  ('GL000144', 'DM0018', 'XH.2.17', 'Lấy đồ vật từ bạn cùng lứa khi được đưa.', 'Trẻ lấy đồ vật một cách đều đặn kèm giao tiếp mắt khi một bạn cùng lứa đưa cho.', 7, 1),
  ('GL000145', 'DM0018', 'XH.2.18', 'Chuyển đồ vật cho bạn cùng lứa tại bàn hoặc trong nhóm khi được yêu cầu.', 'Trẻ phản ứng lại một cách nhất quán phù hợp với các yêu cầu về đồ vật trong các tình huống ở nhóm nhỏ (VD: vòng tròn buổi sáng, bàn ăn bữa phụ, bàn vẽ/nghệ thuật, góc diễn kịch).', 8, 1),
  ('GL000146', 'DM0018', 'XH.2.19', 'Thỉnh thoảng bắt chước hành vi của bạn cùng lứa trong các hoạt động chơi.', 'Trong suốt các hoạt động chơi song song, trẻ sẽ bắt chước một vài hành động của bạn cùng lứa một cách tự phát.', 9, 1),
  ('GL000147', 'DM0018', 'XH.2.20', 'Chơi các trò chơi ghép tranh (theo trí nhớ, lô tô….) một mình và với bạn cùng lứa.', 'Đạt yêu cầu nếu trẻ biết chơi theo lượt với bạn và hoàn thành trò chơi ghép tranh. Chỉ cần có các kỹ năng này là vượt qua mục này.', 10, 1),
  ('GL000148', 'DM0019', 'BC.2.1', 'Bắt chước gần đúng các nguyện âm và phụ âm trong các giao tiếp có nghĩa.', 'Gồm 4 – 5 các nguyên âm khác nhau và 4 – 5 phụ âm khác nhau.', 1, 1),
  ('GL000149', 'DM0019', 'BC.2.2', 'Bắt chước âm thanh của loài vật và những âm thanh khác.', 'Bắt chước được ít nhất 5 âm thanh khác nhau.', 2, 1),
  ('GL000150', 'DM0019', 'BC.2.3', 'Bắt chước một cách tự phát và thường xuyên các từ đơn trong các tương tác.', 'Bắt chước 10 từ (gần đúng) hoặc hơn.', 3, 1),
  ('GL000151', 'DM0019', 'BC.2.4', 'Bắt chước các chuyển động trong 5 bài hát, bắt chước ít nhất là 10 hành động khác nhau.', 'Có một số hành động quen thuộc; không nhắc.', 4, 1),
  ('GL000152', 'DM0019', 'BC.2.5', 'Bắt chước/Mô phỏng các hành động mới trong các bài hát.', 'Thực hiện được gần đúng tối thiểu 5 hành động ở ngay lần làm mẫu đầu tiên.', 5, 1),
  ('GL000153', 'DM0019', 'BC.2.6', 'Bắt chước các hành động với đồ vật – có nhiều bước khác nhau (hoạt động chơi).', 'Việc này bao gồm bắt chước một chuỗi gồm 3 hành động có liên quan hoặc nhiều hơn (VD: mở nắp hộp phân loại hình khối, lấy các hình khối ra, đậy nắp lại và sắp xếp các hình khối).', 6, 1),
  ('GL000154', 'DM0019', 'BC.2.7', 'Bắt chước cá hành động chơi giả vờ với mô hình, tự với bản thân hoặc với bạn.', 'Trẻ bắt chước một cách nhất quán tối thiểu 4 hành động chơi giả vờ với mô hình theo tự nhiên, với bản thân cũng như với bạn.', 7, 1),
  ('GL000155', 'DM0019', 'BC.2.8', 'Bắt chước 2 chuỗi chuyển động trong bài hát/trò chơi.', 'Trẻ bắt chước một cách tự phát 2 hoặc nhiều hơn các hành động trong mỗi bài hát đơn mà không cần nhắc nhở hay chờ đợi.', 8, 1),
  ('GL000156', 'DM0019', 'BC.2.9', 'Bắt chước các cụm 2 từ.', 'Trẻ bắt chước một cách đều đặn các cụm 2 từ.', 9, 1),
  ('GL000157', 'DM0020', 'NT.2.1', 'Ghép/Phân loại theo hình dạng.', 'Ghép và phân loại ít nhất 5 hình dạng khác nhau.', 1, 1),
  ('GL000158', 'DM0020', 'NT.2.2', 'Ghép/Phân loại theo kích cỡ.', 'Ghép và phận loại được ít nhất 3 kích cỡ khác nhau của các đồ vật giống nhau.', 2, 1),
  ('GL000159', 'DM0020', 'NT.2.3', 'Ghép/Phân loại theo kiểu dáng, đường nét.', 'Trẻ ghép và phân loại theo kiểu dáng, đường nét.', 3, 1),
  ('GL000160', 'DM0020', 'NT.2.4', 'Phân loại các đồ vật tương tự nhau vào các nhóm (dựa theo một danh tính chung).', 'Trẻ ghép và phân loại các đồ vật không giống nhau dựa theo một danh tính chung (VD: các ô tô, các con ngựa, tất, bóng, giày, cốc).', 4, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000161', 'DM0020', 'NT.2.5', 'Phân loại các đồ vật thông dụng vào các nhóm theo chức năng.', 'Trẻ nhóm các đồ vật theo chức năng: ăn, mặc, đồ chơi, vẽ.', 5, 1),
  ('GL000162', 'DM0020', 'NT.2.6', 'Tìm kiếm/Yêu cầu đồ vật bị mất/còn thiếu.', 'Trẻ nhận biết được khi thiếu một đồ vật trong một bộ và có yêu cầu về đồ vật đó hoặc tìm kiếm nó (VD: một miếng ghép bị thiếu, một chiếc giày bị mất, một chiếc cốc bị thiếu).', 6, 1),
  ('GL000163', 'DM0020', 'NT.2.7', 'Ghép/Phân loại theo 2 tiêu chí.', 'Trẻ ghép/phân loại các đồ vật theo màu sắc và hình dạng, hoặc hình dạng và kích cỡ…', 7, 1),
  ('GL000164', 'DM0020', 'NT.2.8', 'Ghép nhóm số lượng từ 1 đến 3.', 'Trẻ ghép các đồ vật khác nhau vào nhóm có số lượng từ 1 – 3 (VD: các miếng ghép domino, các miếng ghép hình thú trên đĩa).', 8, 1),
  ('GL000165', 'DM0021', 'C.2.1', 'Kết hợp 2 đồ vật có liên quan trong trò chơi (bộ chén và đĩa nhỏ, bộ thìa và đĩa).', 'Trẻ thể hiện nhận thức về chức năng liên quan đến bộ trò chơi.', 1, 1),
  ('GL000166', 'DM0021', 'C.2.2', 'Bắt chước/Phát ra âm thanh tương ứng trong trò chơi (nói chuyện điện thoại, giả tiếng ồn ô tô, tiếng các loài vật).', 'Đạt yêu cầu nếu trẻ tạo ra được 5 âm thanh hoặc nhiều hơn trong trò chơi.', 2, 1),
  ('GL000167', 'DM0021', 'C.2.3', 'Thực hiện hành động đơn lẻ với trang phục hay đồ vật gì đó trên búp bê hay con vật.', 'Trẻ cần tự phát hành động: không đạt nếu chỉ bắt chước.', 3, 1),
  ('GL000168', 'DM0021', 'C.2.4', 'Kết hợp các hành động theo chức năng có liên quan đến một chủ đề chơi nào đó (cho ăn uống, đặt lên giường và đắp chăn).', 'Trẻ cần tự phát thực hiện liên tiếp tối thiểu 2 hành động có liên quan đến một hoạt động. Không vượt qua nếu chỉ bắt chước.', 4, 1),
  ('GL000169', 'DM0021', 'C.2.5', 'Thể hiện khả năng giải quyết vấn đề bằng việc “thử và sai” với đồ chơi xây dựng; cách thức linh hoạt, không lặp đi lặp lại.', 'Vượt qua nếu trẻ có thử nghiệm và giải quyết vấn đề khi mắc lỗi trong trò chơi có đồ vật.', 5, 1),
  ('GL000170', 'DM0022', 'C.2.6', 'Chơi phù hợp và linh hoạt trong 10 phút mà thỉnh thoảng người lớn mới phải để ý đến.', 'Người lớn có thể đưa ra một vài bộ xếp hình hoặc các dụng cụ hình ảnh không gian, nhưng trẻ cần chơi một mình bằng cách thực hiện trò chơi phù hợp mà không cần chỉ dẫn bằng lời quá 2 lần, thì cho vượt qua mục này. Không phạt/vẫn cho qua nếu có một số hành động lặp đi lặp lại trong trò chơi.', 1, 1),
  ('GL000171', 'DM0022', 'C.2.7', 'Có thể tự thích ứng một cách phù hợp với các vật liệu chơi mở đầu – kết thúc trong ít nhất 10 phút thỉnh thoảng có sự hướng dẫn của người lớn.', 'Người lớn có thể bày vật liệu ra (đất nặn, các dụng cụ nghệ thuật, sách, đồ để chơi giả vờ), nhưng trẻ cần chơi một mình bằng cách thực hiện các hành động chơi phù hợp không cần quá 2 chỉ dẫn bằng lời thì vượt qua mục này.', 2, 1),
  ('GL000172', 'DM0022', 'C.2.8', 'Lấy đồ vật, mang tới bàn, hoàn thành nhiệm vụ chơi và cất đồ.', 'Trẻ chơi độc lập gồm lấy dụng cụ, di chuyển đến địa điểm chơi, biết thu dọn và cất dụng cụ khi kết thúc. Việc này có thể bao gồm cả các hoạt động chơi tự do theo hướng mở và có kết thúc.', 3, 1),
  ('GL000173', 'DM0023', 'VDT.2.1', 'Đặt 3 hình hoặc nhiều hơn vào đúng khuôn hình.', 'Trẻ hoàn thành đặt hình dạng vào khuôn một cách độc lập; có thể thử và mắc lỗi nhưng không được nhắc hay hỗ trợ.', 1, 1),
  ('GL000174', 'DM0023', 'VDT.2.2', 'Xếp chồng 8 – 10 khối có kích cỡ 1 inch.', 'Trẻ tự mình dựng một hình tháp gồm 8 – 10 khối gỗ giữ được thăng bằng.', 2, 1),
  ('GL000175', 'DM0023', 'VDT.2.3', 'Sao chép 3 hoặc nhiều hơn mô hình khối đơn giản.', 'Trẻ sao chép một vài mô hình khối bao gồm tối thiểu 3 khối gỗ (VD: tháp thẳng đứng, đường ngang, cây cầu).', 3, 1),
  ('GL000176', 'DM0023', 'VDT.2.4', 'Ghép theo các cách khác nhau 5 hoặc nhiều hơn các khối xếp hình, xâu hạt, khối gỗ.', 'Trẻ sử dụng các dạng đồ vật đan cài vào nhau và lắp ráp số lượng 5 hoặc nhiều hơn theo một số cách khác nhau.', 4, 1),
  ('GL000177', 'DM0023', 'VDT.2.5', 'Bắt chước 5 hoặc nhiều hơn các hành động đơn giản trong trò chơi với đất nặn (lăn tròn, chọc, vỗ dẹt, nặn).', 'Tự diễn giải.', 5, 1),
  ('GL000178', 'DM0023', 'VDT.2.6', 'Dán các miếng dán đa dạng lên giấy.', 'Người lớn có thể phải giúp bóc một góc để trẻ bóc được miếng dán ra, nhưng trẻ phải tự bóc hẳn miếng dán ra khỏi tờ miếng dán và dán vào tờ giấy một cách độc lập.', 6, 1),
  ('GL000179', 'DM0023', 'VDT.2.7', 'Mở ra và đóng vào các hộp đựng khác nhau, trong đó có loại có nắp vặn xoáy.', 'Đây không phải là một bài kiểm tra về sức khỏe – nắp nên dễ mở.', 7, 1),
  ('GL000180', 'DM0023', 'VDT.2.8', 'Kéo khóa và mở khóa.', 'Trẻ có thể tự kéo khóa hết xuống; trẻ có thể kéo khóa lên trên cùng; mặc dù người lớn có thể phải giúp chập 2 đường khóa vào nhau cho trẻ.', 8, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000181', 'DM0023', 'VDT.2.9', 'Xâu các đồ vật với nhau bằng dây thừng, dây to bản.', 'Trẻ xâu tối thiểu 5 hạt, các miếng hình mì ống, các vòng nhẫn….vào 1 dây to mà không cần trợ giúp hay nhắc nhở.', 9, 1),
  ('GL000182', 'DM0023', 'VDT.2.10', 'Bắt chước các đường nét, chữ viết nguệch ngoạc, các dấu chấm bằng bút dầu, bút chì màu.', 'Trẻ bắt chước tối thiểu 3 hình thức hành động khác nhau với các dụng cụ viết.', 10, 1),
  ('GL000183', 'DM0023', 'VDT.2.11', 'Cắt giấy bằng kéo.', 'Không cần phải cắt rời. Có thể sử dụng kéo của trẻ hoặc của người lớn. Ngườ lớn có thể chỉ cách cầm kéo nhưng trẻ phải tự cắt. Không cần phải cầm kéo một cách hoàn hảo. Cần phải thực hiện được 3 lần cắt.', 11, 1),
  ('GL000184', 'DM0023', 'VDT.2.12', 'Đặt miếng nhựa dẹt và đồng xu vào một khe cắm.', 'Trẻ tự đặt 5 miếng hoặc nhiều hơn trên bàn và đặt từng miếng vào khe, cả theo đường thẳng và ngang mà không cần nhắc nhở, và thành công với các đồng xu.', 12, 1),
  ('GL000185', 'DM0023', 'VDT.2.13', 'Xâu chuỗi các hạt khác nhau bằng nhiều loại dây khác nhau.', 'Trẻ có thể xâu chuỗi các đồ vật trên nhiều loại dây khác nhau.', 13, 1),
  ('GL000186', 'DM0023', 'VDT.2.14', 'Hoàn thành bảng ghép hình gồm 4 – 6 miếng khớp với nhau.', 'Trẻ tự hoàn thành bảng ghép; có thể thử nghiệm và mắc lỗi nhưng không được nhắc hay hỗ trợ.', 14, 1),
  ('GL000187', 'DM0024', 'VDTH.2.1', 'Bắt chước các hành động vận động thô ở nhiều tình huống khác nhau (ngồi, đứng, di chuyển).', 'Trẻ có thể bắt chước một cách nhất quán và tự phát các hành động (có thể được hướng dẫn) bất kể là ở chỗ nào.', 1, 1),
  ('GL000188', 'DM0024', 'VDTH.2.2', 'Nhảy xuống một bậc và nhảy qua chướng ngại vật trên mặt đất.', 'Trẻ nhảy và di chuyển về địa điểm nào đó, từ một bậc thấp đến một mặt phẳng.', 2, 1),
  ('GL000189', 'DM0024', 'VDTH.2.3', 'Sử dụng một số trang thiết bị ở sân chơi (trèo, trượt).', 'Trẻ khởi xướng một cách nhất quán các hành động phù hợp với một số trang thiết bị thấp ở sân chơi.', 3, 1),
  ('GL000190', 'DM0024', 'VDTH.2.4', 'Ngồi trên xe 3 bánh và đẩy bằng chân hoặc bắt đầu với bàn đạp.', 'Trẻ tự ngồi lên xe 3 bánh đúng chỗ để lái và cố gắng/thử đạp bàn đạp nhưng có thể càn sự hỗ trợ.', 4, 1),
  ('GL000191', 'DM0024', 'VDTH.2.5', 'Kéo xe hoặc đẩy xe cút kít.', 'Trẻ có thể tự xoay sở với xe kéo hoặc xe cút kít để di chuyển đồ vật trên sân chơi.', 5, 1),
  ('GL000192', 'DM0024', 'VDTH.2.6', 'Đá bóng vào mục tiêu.', 'Trẻ đá quả bóng lớn vào trúng đích.', 6, 1),
  ('GL000193', 'DM0024', 'VDTH.2.7', 'Đào bằng xẻng.', 'Trẻ đào bằng xẻng, xúc vật liệu lên, và tự chuyển vào thùng/hộp chứa.', 7, 1),
  ('GL000194', 'DM0025', 'TL.2.1', 'Sử dụng khăn ăn khi có gợi ý.', 'Khi được hướng dẫn nhưng không trợ giúp, trẻ cầm khăn ăn lên và lau một cách phù hợp ở mỗi phần hướng dẫn. Không cần làm suốt mà chỉ cần làm lướt qua một chút.', 1, 1),
  ('GL000195', 'DM0025', 'TL.2.2', 'Tự lấy thức ăn từ bát với các dụng cụ.', 'Khi người lớn cầm hoặc đặt bát hoặc đĩa trước trẻ, trẻ sử dụng dụng cụ ăn để chuyển đồ ăn sang đĩa của nó một cách độc lập. Có thể lung túng. Người lớn có thể dùng tín hiệu.', 2, 1),
  ('GL000196', 'DM0025', 'TL.2.3', 'Chuyển các hộp đựng khi được hướng dẫn.', 'Tại bàn, khi một người yêu cầu trẻ chuyển đồ, trẻ nhìn đồ vật đó và cầm lên, sau đó chuyển nó cho người ở bên trái hoặc phải. Trẻ cần phản ứng lại với yêu cầu bằng cách tìm kiếm đồ vật và cố gắng tự cầm nó lên. Nếu ai đó chuyển một hộp đựng cho trẻ và hướng dẫn trẻ chuyển nó cho người kế tiếp, trẻ làm theo chỉ dẫn mà không cần nhắc nhở.', 3, 1),
  ('GL000197', 'DM0025', 'TL.2.4', 'Mang đĩa, cốc và đồ ăn bằng bạc (kim loại) ra bồn khi ăn xong.', 'Khi trẻ rời bàn, trẻ làm theo các hướng dẫn của người lớn là mang đi một số đồ vật nào đó tới một địa điểm cụ thể mà không cần nhắc nhở.', 4, 1),
  ('GL000198', 'DM0025', 'TL.2.5', 'Duy trì ở tại bàn ăn cùng người khác trong suốt thời gian ăn.', 'Trẻ ngồi trong suốt bữa ăn và ở nguyên không cần nhắc hoặc trợ giúp cho đến khi ăn xong, và người lớn ra tín hiệu là nó có thể đi.', 5, 1),
  ('GL000199', 'DM0025', 'TL.2.6', 'Ăn uống và cư xử một cách phù hợp ở cửa hàng đồ ăn nhanh.', 'Trẻ tham gia tất cả các bước trong bữa ăn nhanh – chờ đợi, yêu cầu món, mang đi, ngồi, ăn, dọn, và rời khỏi mà không cần nhắc nhở. Trẻ ngồi cho đến khi kết thúc và cho đến khi người khi ăn xong. Trẻ vui vẻ đi bộ cùng người lớn ra cửa. Không cần người lớn phải giữ tay.', 6, 1),
  ('GL000200', 'DM0025', 'TL.2.7', 'Chạm hoặc thử một đồ ăn mới đã được giới thiệu nhiều lần.', 'Trẻ phản ứng lại một cách vui vẻ với hướng dẫn nếm hoặc cắn hay uống một món nào đó.', 7, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000201', 'DM0025', 'TL.2.8', 'Ăn tất cả các nhóm thức ăn.', 'Trẻ tự phát ăn một số quả/rau, bơ, sữa, ngũ cốc, và thịt (ngoại trừ những hạn chế thường xuyên nào đó).', 8, 1),
  ('GL000202', 'DM0025', 'TL.2.9', 'Tự uống nước.', 'Trẻ tự phát lấy cốc và lấy nước từ vòi hoặc tủ lạnh mà không cần bất kì một hướng dẫn hoặc trợ giúp nào từ phía người lớn. Khi dùng xong, trẻ vặn vòi lại một cách tự phát.', 9, 1),
  ('GL000203', 'DM0026', 'TL.2.10', 'Tự cởi quần áo và bỏ vào giỏ đựng quần áo bẩn (quần áo không có nút/khuy).', 'Khi được hướng dẫn, trẻ cởi áo, quần, quần áo lót, tất và giày mà không cần trợ giúp của người khác, và đặt tất cả quần áo vào nơi đựng phù hợp. Có thể nhắc bằng lời hoặc dùng cử chỉ/điệu bộ 1 hoặc 2 lần, nhưng không nhắc bằng hành động.', 1, 1),
  ('GL000204', 'DM0026', 'TL.2.11', 'Tự thực hiện được một số bước mặc quần áo (cần hỗ trợ nếu có nút/khuy).', 'Tự giải thích.', 2, 1),
  ('GL000205', 'DM0026', 'TL.2.12', 'Cởi bỏ áo khoác, mũ (không có khóa, dây buộc) và treo trên móc.', 'Tự cởi bỏ áo khoác và mũ; có thể được nhắc treo vào đúng chỗ.', 3, 1),
  ('GL000206', 'DM0027', 'TL.2.13', 'Lau mặt bằng khăn ẩm khi được hướng dẫn.', 'Sau khi người lớn đưa khăn ẩm và hướng dẫn “Lau mặt con đi”, trẻ lau toàn bộ mặt mà không cần trợ giúp thêm, sau đó đưa lại, hoặc đặt xuống khi xong.', 1, 1),
  ('GL000207', 'DM0027', 'TL.2.14', 'Lau mũi khi được hướng dẫn.', 'Khi được hướng dẫn xì hoặc lau mũi, trẻ đi tới hộp đựng khăn giấy, lấy giấy, xì hoặc lau mũi, và ném giấy đi mà không cần thêm một lời nhắc nào.', 2, 1),
  ('GL000208', 'DM0027', 'TL.2.15', 'Thực hiện tất cả các bước rửa tay.', 'Trẻ thực hiện đều đặn hành động cho mỗi bước rửa tay chứ không chỉ là vặn nước mà không cần sự nhắc nhở nào bằng hành động. Người lớn có thể nhắc một số bước bằng cử chỉ/điệu bộ hoặc một phần bằng hành động.', 3, 1),
  ('GL000209', 'DM0027', 'TL.2.16', 'Hợp tác khi được gội đầu/cắt tóc.', 'Trẻ không chống cự, khóc hoặc các hành động chống đối khi chải đầu hay cắt tóc. Trẻ tham gia bằng cách trợ giúp lau dầu gội, lau khăn. Có thể sử dụng các dụng cụ thúc đẩy mạnh mẽ trong quá trình thực hiện.', 4, 1),
  ('GL000210', 'DM0027', 'TL.2.17', 'Chơi với 5 đồ chơi khi đi tắm một cách phù hợp.', 'Tự giải thích – đối với những đồ chơi khi đi tắm thông thường.', 5, 1),
  ('GL000211', 'DM0027', 'TL.2.18', 'Cất đồ chơi đi theo yêu cầu khi tắm xong.', 'Trẻ phải đặt tất cả đồ chơi khi tắm vào hộp chứa phù hợp mà không cần nhắc nhở thêm sau khi đã có hướng dẫn khởi đầu.', 6, 1),
  ('GL000212', 'DM0027', 'TL.2.19', 'Hỗ trợ bôi kem dưỡng da.', 'Trẻ trợ giúp cha mẹ bằng cách thoa kem lên tay, cánh tay, chân, bụng.', 7, 1),
  ('GL000213', 'DM0027', 'TL.2.20', 'Chà bàn chải đánh răng trên bề mặt răng.', 'Trể chà bàn chải lên hàm dưới và hàm trên, ở trước và ở trong khi được hướng dẫn. Có thể nhắc ở các cấp độ hoặc bằng hành động.', 8, 1),
  ('GL000214', 'DM0027', 'TL.2.21', 'Tự đi ngủ sau khi hoàn thành các hoạt động theo thói quen trước giờ đi ngủ.', 'Trẻ ngủ trên giường của nó và đi ngủ mà không cần sự hiện diện của người lớn trong phòng khi đến giờ và đèn tắt.', 9, 1),
  ('GL000215', 'DM0027', 'TL.2.22', 'Hiểu chuỗi thói quen trước giờ đi ngủ.', 'Trẻ hiểu thói quen trước giờ đi ngủ bằng cách khởi xướng 1 hoặc nhiều hoạt động, và tham gia thực hiện các bước khác nhau theo thói quen mà không cần nhắc nhở hoàn toàn.', 10, 1),
  ('GL000216', 'DM0028', 'TL.2.23', 'Sắp xếp các dụng cụ bằng bạc (kim loại) từ bồn rửa/máy rửa bát vào khay đựng.', 'Người lớn có thể đặt ra tình huống, nhưng sau khi đặt ra và hướng dẫn, trẻ lấy được khoảng 20 đồ ăn từ bồn và đặt chúng vào khay mà không cần bất kì sự trợ giúp nào từ phía người lớn.', 1, 1),
  ('GL000217', 'DM0028', 'TL.2.24', 'Tháo đồ từ máy sấy khô cho vào giỏ.', 'Khi bố hoặc mẹ mở máy sấy và đưa giỏ, trẻ kéo tất cả các thứ trong máy sáy ra và cho vào giỏ mà không cần nhắc nhở thêm. Trẻ có thể cần trọ giúp thêm ở một mục khó nào đó.', 2, 1),
  ('GL000218', 'DM0028', 'TL.2.25', 'Xếp đôi tất với nhau.', 'Thực hiện với khoảng một nhóm 10 đôi tất hoặc hơn trong một giỏ, trẻ để tất theo đôi, gập hoặc xếp chúng lại, sau đó thả vào thùng chứa.', 3, 1),
  ('GL000219', 'DM0028', 'TL.2.26', 'Đổ nước/thức ăn vào đĩa dành cho vật nuối.', 'Người lớn có thể cung cấp vật liệu và hướng dẫn, nhưng trẻ phải thực hiện hành động mà không cần trợ giúp thêm.', 4, 1),
  ('GL000220', 'DM0029', 'GTN.3.1', 'Tập trung chú ý và tham gia với sự thích thú trong 5-10 phút khi người lớn đọc một cuốn sách quen thuộc có sử dụng các câu đơn giản.', 'Ở cùng với người lớn, rất tập trung chú ý và tham gia vào câu chuyện mà người lớn đang đọc. Các VD như giao tiếp mắt giữa các trang sách và người lớn, chỉ vào tranh ảnh trong sách, lật các trang sách, nói tên các bức tranh trong sách.', 1, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000221', 'DM0029', 'GTN.3.2', 'Thực hiện các câu lệnh mới có 1 yêu cầu với các đồ vật / hành động quen thuộc.', 'Thực hiện chỉ dẫn bằng cách nhìn vào người lớn và thực hiện hành động mà không cần người lớn phải dùng cử chỉ/điệu bộ hoặc hành động để hướng dẫn. Người lớn có thể nhắc lại chỉ dẫn một lần nữa mà không cần ra tín hiệu cử chỉ/điệu bộ.', 2, 1),
  ('GL000222', 'DM0029', 'GTN.3.3', 'Nhận diện được nhiều đồ vật phổ biến và tranh ảnh về chúng: quần áo, đồ dùng ăn uống,vệ sinh, chơi, thức ăn.', 'Vượt qua nếu nhận được hơn 50 đồ vật phổ biến hoặc hơn.', 3, 1),
  ('GL000223', 'DM0029', 'GTN.3.4', 'Phản ứng lại một cách phù hợp với câu hỏi "có/ không" về sở thích.(Nói kèm giao tiếp mắt)', 'Nói " có/ không" phù hợp với ngữ cảnh yêu cầu hoặc từ chối. Cần có cả giao tiếp mắt, mặc dù không cần đi kèm cử chỉ/điệu bộ(VD: gật/ lắc đầu). Có thể sử dụng các cụm như " yes, please", " không, cảm ơn".', 4, 1),
  ('GL000224', 'DM0029', 'GTN.3.5', 'Nhận ra hoặc 5 hoặc nhiều hơn các hành động trong tranh hoặc sách (Phát âm và / hoặc ra cử chỉ/điệu bộ)', 'Phát âm và / hoặc ra cử chỉ/điệu bộ (VD chỉ tay) đáp lại câu hỏi của người lớn. Các VD: "Chỉ cho cô em bé đang ngủ?" hoặc " Con có nhìn thấy con chó đang chạy không?". Phản ứng không cần đi kèm với giao tiếp mắt.', 5, 1),
  ('GL000225', 'DM0029', 'GTN.3.6', 'Làm theo hai hoặc nhiều hơn các chỉ dẫn được đưa ra trong tình huống quen thuộc hàng ngày (giờ đi ngủ: lấy một quyển sách và vào giường; lấy bằng chải và kem đánh răng).', 'Đều đặn làm theo chỉ dẫn từ 2 - 3 phần gồm các hành động và đồ vật theo thói quen đã được làm hàng ngày.', 6, 1),
  ('GL000226', 'DM0029', 'GTN.3.7', 'Hiểu được mối liên hệ về không gian của các đồ vật (VD: dưới, cạnh).', 'Các VD là sử dụng các khái niệm một cách phù hợp khi được đề nghị (" Đặt quả bóng ở cạnh xe ô tô " hoặc " Đặt quả bóng ở dưới gầm bàn ").', 7, 1),
  ('GL000227', 'DM0029', 'GTN.3.8', 'Phân biệt được những khái niệm ban đầu về kích cỡ- to/ nhỏ', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật) để phản ứng lại với câu hỏi của người lớn. Các VD: " Quả bóng to đâu?" hoặc " Chỉ cho cô chiếc ô tô nhỏ". Phản ứng lại không cần đi kèm giao tiếp mắt.', 8, 1),
  ('GL000228', 'DM0029', 'GTN.3.9', 'Phân biệt được tối thiểu là 4 màu sắc khác nhau theo yêu cầu.', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật) để phản ứng lại với yêu cầu của người lớn. Các VD: " Bút màu xanh da trời đâu?" hoặc " Chỉ cho cô chiếc xe tải màu đỏ". Phản ứng lại không cần đi kèm giao tiếp mắt.', 9, 1),
  ('GL000229', 'DM0029', 'GTN.3.10', 'Nhận ra được 20 âm thanh (VD: tiếng con vật, chuông điện thoại; " Con gì kêu '' meo meo''?").', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật) để phản ứng lại với câu hỏi của người lớn. Các VD: " Con gì kêu '' meo meo''?", " Con chó kêu thế nào nhỉ" hoặc " Con nghe thấy gì?". Phản ứng lại không cần đi kèm giao tiếp mắt.', 10, 1),
  ('GL000230', 'DM0029', 'GTN.3.11', 'Hiểu được chức năng của các đồ vật thông thường/ phổ biến (đi xe, xắt, ăn, ngủ, đi vào chân, uống,..).', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật) để phản ứng lại với câu hỏi của người lớn. Các VD: " Chúng ta lái bằng gì?" hoặc " Chúng ta dùng gì để uống?". Phản ứng lại không cần đi kèm giao tiếp mắt. Vượt qua khi xác định tối thiểu 3 chức năng của đồ vật.', 11, 1),
  ('GL000231', 'DM0029', 'GTN.3.12', 'Hiểu được các đại từ sở hữu " của tôi" và " của bạn".', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật) để phản ứng lại với câu hỏi của người lớn. Người lớn có thể sử dụng một đồ vật thuộc sở hữu của trẻ để thăm dò khả năng hiểu. Các VD: " Lượt này của ai?" hoặc " Chiếc giày này của ai?". Phản ứng lại không cần đi kèm giao tiếp mắt.', 12, 1),
  ('GL000232', 'DM0029', 'GTN.3.13', 'Xác định được 10 hành động thông qua tranh ảnh, chọn lựa, thể hiện hành động', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: chỉ tay, cầm đồ vật, thể hiện hành động) để phản ứng lại với câu hỏi của người lớn. Các VD: " Chỉ cho cô cách con ném bóng" hoặc " Cho cô xem con lợn đang ăn".', 13, 1),
  ('GL000233', 'DM0029', 'GTN.3.14', 'Làm theo hai hoặc nhiều hơn các chỉ dẫn độc lập trong ngữ cảnh mới lạ', 'Hoàn thành chỉ dẫn bằng cách nhìn vào người lớn và thực hiện hành động mà không cần chỉ dẫn bằng cử chỉ/điệu bộ hoặc hành động của người lớn. Người lớn có thể nhắc lại chỉ dẫn một lần nữa mà không cần dùng tín hiệu cử chỉ/điệu bộ. Các VD: " Đưa cho cô chiếc xe ô tô và đóng sách lại" hoặc " Đặt quả bóng vào xô, và đặt búp bê lên bàn"', 14, 1),
  ('GL000234', 'DM0030', 'GTD.3.1', 'Nói được cụm 2-3 từ cho các ngữ cảnh giao tiếp khác nhau (VD: yêu cầu, chào hỏi, thu hút sự chú ý, phản đối)', 'Phát âm cần kèm cả giao tiếp mắt. Các VD: " Muốn thêm nước hoa quả". " Tạm biệt Sally". " Giúp con mở" hoặc " Không bóng". Phát âm không cần hoàn hảo.', 1, 1),
  ('GL000235', 'DM0030', 'GTD.3.2', 'Nói được các câu 2 từ trở lên để bình luận với người khác', 'Phát âm cần kèm cả giao tiếp mắt và không liên quan đến việc được yêu cầu bình luận về đồ vật hoặc hành động. Các VD: " Xem con bò". " Máy bay bay nhanh" hoặc " Con cho con". Phát âm không cần hoàn hảo.', 2, 1),
  ('GL000236', 'DM0030', 'GTD.3.3', 'Gọi tên được các hành động trong tranh và sách.', 'Phát âm không cần kèm cả giao tiếp mắt. Các VD: " Em bé ăn" hoặc " Con chim bay". Phát âm không cần hoàn hảo.', 3, 1),
  ('GL000237', 'DM0030', 'GTD.3.4', 'Bình luận và yêu cầu về vị trí (lên, xuống, trong, trên)', 'Phát âm cần kèm cả giao tiếp mắt. Các VD: " Con chó trên bàn" hoặc " Quả bóng ở đó".Phát âm không cần hoàn hảo.', 4, 1),
  ('GL000238', 'DM0030', 'GTD.3.5', 'Bình luận và yêu cầu bằng cách sử dụng cấu trúc sở hữu đơn giản (của tôi, của bạn)', 'Phát âm cần kèm cả giao tiếp mắt. Người lớn có thể sử dụng một đồ vật thuộc sở hữu của trẻ. Các VD: " Cái đó (cốc) của con" hoặc " Lượt cô" hoặc " Em bé của con". Phát âm không cần hoàn hảo.', 5, 1),
  ('GL000239', 'DM0030', 'GTD.3.6', 'Thể hiện cử chỉ/điệu bộ hoặc nói " Tôi/ con không biết" trong ngữ cảnh', 'Phát âm hoặc dùng cử chỉ/điệu bộ (VD: nhún vai, giơ hai tay lên) cần bao gồm cả giao tiếp mắt.', 6, 1),
  ('GL000240', 'DM0030', 'GTD.3.7', 'Sử dụng tên của người khác một cách nhất quán khi cần thu hút sự chú ý của họ', 'Phát âm cần kèm cả giao tiếp mắt. Phát âm không cần hoàn hảo.', 7, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000241', 'DM0030', 'GTD.3.8', 'Gửi một thông điệp đơn giản đén người khác (Đi tới nói với mẹ " Con chào mẹ")', 'Phát âm cần kèm cả giao tiếp mắt. Các VD: "Đi tới nói với mẹ '' Con chào mẹ''" hoặc "Đi gọi bố tới đây". Phát âm không cần hoàn hảo.', 8, 1),
  ('GL000242', 'DM0030', 'GTD.3.9', 'Nói " Xin chào" và " Tạm biệt" một cách phù hợp, cả khởi xướng và hồi đáp lại.', 'Phát âm cần kèm cả giao tiếp mắt.', 9, 1),
  ('GL000243', 'DM0030', 'GTD.3.10', 'Sử dụng đúng các đại từ chỉ bản thân và người khác (các biến thể tôi và bạn)', 'Phát âm cần kèm cả giao tiếp mắt. Người có thể muốn sử dụng gương để thăm dò. Phản ứng có thể gồm các biến thể " bạn và tôi". Các VD : " Đó là con" hoặc " Con thấy mẹ/ cô…"', 10, 1),
  ('GL000244', 'DM0030', 'GTD.3.11', 'Sử dụng các từ và điệu bộ cử chỉ đơn giản để diễn tả trải nghiệm cá nhân.', 'Phát âm và / hoặc cử chỉ/điệu bộ (VD: làm hành động) cần kèm cả giao tiếp mắt. Trẻ có thể sử dụng các từ đơn hoặc các cụm đơn giản. Các VD: " Con chó con", " Bắt bóng" hoặc " Bóng bay lên". Phát âm không cần hoàn hảo.', 11, 1),
  ('GL000245', 'DM0030', 'GTD.3.12', 'Gọi tên 1 đến 2 màu sắc (tên sự vật+ màu sắc)', 'Phát âm không cần kèm cả giao tiếp mắt. Người lớn có thể hỏi " Xe ô tô màu gì?" nhưng trẻ cần tự trả lời (" ô tô đỏ", " đó là quả bóng màu xanh"). Từ tương đương cũng chấp nhận được.', 12, 1),
  ('GL000246', 'DM0030', 'GTD.3.13', 'Phản ứng lại một cách phù hợp với câu hỏi " Cái gì?"', 'Phát âm không cần kèm cả giao tiếp mắt. Người lớn có thể hỏi lại lần nữa.', 13, 1),
  ('GL000247', 'DM0030', 'GTD.3.14', 'Phản ứng lại một cách phù hợp với câu hỏi " Ở đâu?"', 'Phát âm không cần kèm cả giao tiếp mắt. Người lớn có thể hỏi lại lần nữa.', 14, 1),
  ('GL000248', 'DM0030', 'GTD.3.15', 'Phản ứng lại một cách phù hợp với câu hỏi " Ai?"', 'Phát âm không cần kèm cả giao tiếp mắt. Người lớn có thể hỏi lại lần nữa.', 15, 1),
  ('GL000249', 'DM0030', 'GTD.3.16', 'Hỏi các câu hỏi " Có/ không" đơn giản bằng cách tăng ngữ điệu (có thể tăng ngữ điệu ở câu có 1 từ)', 'Phát âm cần kèm cả giao tiếp mắt. Câu hỏi có thể là câu có 1 từ với ngữ điệu tăng. Các VD : " Bánh ?" hoặc " Đi?"', 16, 1),
  ('GL000250', 'DM0030', 'GTD.3.17', 'Hỏi các câu hỏi " Cái gì?" và " Ở đâu?"', 'Phát âm cần kèm cả giao tiếp mắt. Cần hỏi được hai loại câu hỏi thì vượt qua.', 17, 1),
  ('GL000251', 'DM0030', 'GTD.3.18', 'Trả lời một số câu hỏi thông tin đơn giản: tên, tuổi, màu sắc áo,...', 'Phát âm không cần kèm cả giao tiếp mắt. Các VD: " Tên con là gì?", " Còn bao nhiêu tuổi?", hoặc " Áo con màu gì?".', 18, 1),
  ('GL000252', 'DM0031', 'XH.3.1', 'Chơi các trò chơi vận động thô đơn giản (Ví dụ: bóng, trốn tìm, trò chơi vòng tròn)', 'Có tối thiểu 2 lần tham gia các hành động tích cực (chạm tới, bắt chước, phát âm) trong ít nhất 3 trò chơi. Chỉ giao tiếp mắt và cười là không đủ. Các ví dụ: “trốn tìm”, “chơi vòng quanh”, chơi bóng.', 1, 1),
  ('GL000253', 'DM0031', 'XH.3.2', 'Chia sẻ và chỉ cho xem “đối tượng” khi đối tác yêu cầu', 'Phản ứng lại trong vòng 3 giây với yêu cầu của đối tác. Đối tác có thể lặp lại lần thứ 2. Phản ứng có thể bao gồm phát âm (Ví dụ: “em bé”) hoặc cử chỉ/điệu bộ (Ví dụ: mang đồ vật cho người lớn, cầm đồ vật trong tay).', 2, 1),
  ('GL000254', 'DM0031', 'XH.3.3', 'Bắt chước và thể hiện các bài hát mới/các trò chơi ngón tay trong tính huống nhóm', 'Có tối thiểu 2 lần tham gia các hành động tích cực trong 2 thói quen hoặc nhiều hơn. Chỉ giao tiếp mắt và cười là không đủ. Các ví dụ: “các ngón tay ngoắc ngoắc”, “cù”, “nhện giăng tơ” …', 3, 1),
  ('GL000255', 'DM0031', 'XH.3.4', 'Phản ứng lại một cách phù hợp với các yêu cầu/hướng dẫn đơn giản từ các bạn cùng lứa', 'Báo cáo của phụ huynh có thế được chấp nhận. Các ví dụ: “lấy bóng”, “bạn là mẹ”, hoặc “đặt nó ở đây”', 4, 1),
  ('GL000256', 'DM0031', 'XH.3.5', 'Khởi xướng tương tác và bắt chước các bạn cùng lứa', 'Báo cáo của phụ huynh có thể được chấp nhận. Khởi xướng/bắt chước tối thiểu 2 vòng trong ít nhất 3 trò chơi phù hợp độ tuổi (Ví dụ: “đuổi bắt), “trốn tìm”, chơi với đoàn tàu, trang phục)', 5, 1),
  ('GL000257', 'DM0031', 'XH.3.6', 'Chơi đóng vai quen thuộc hàng ngày với bạn cùng lứa', 'Báo cáo của phụ huynh có thể được chấp nhận. Tham gia tối thiểu 2 vòng. Các hành vi có thể gồm phát âm (Ví dụ: “em bé đói”), bắt chước, hoặc quan sát đối tác chơi. Các ví dụ trò chơi quen thuộc hàng ngày như chơi ngôi nhà, mặc quần áo, chơi đóng vai.', 6, 1),
  ('GL000258', 'DM0031', 'XH.3.7', 'Chơi lần lượt trong các trò chơi bảng ghép đơn giản', 'Tham gia vào nhiều hơn 2 vòng trong ít nhất 3 trò chơi phù hợp lứa tuổi. Các ví dụ: “Nối 4 điểm”, “Săn tuần lộc” hoặc “vịt may mắn”.', 7, 1),
  ('GL000259', 'DM0031', 'XH.3.8', 'Sử dụng những thuật ngữ thể hiện sự lịch sự: “Làm ơn”, “cảm ơn”, “xin lỗi”', 'Các ví dụ: “Làm ơn”, “cảm ơn” hoặc “xin lỗi” một cách tự phát và phù hợp. Từ tương đương có thể chấp nhận được. Vượt qua nếu sử dụng thường xuyên được 2 trong 3 từ', 8, 1),
  ('GL000260', 'DM0031', 'XH.3.9', 'Bắt chước một loạt các hành động vận động thô mới lạ khi đứng hoặc khi di chuyển, ví dụ: “làm theo người dẫn đầu” hoặc đi giống các con vật', 'Các ví dụ: “Làm theo người dẫn đầu”, “Simon nói” hoặc giả vờ di chuyển như các con vật. Tự phát bắt chước 10 hành động mới lạ hoặc hơn. Có thể không chính xác', 9, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000261', 'DM0031', 'XH.3.10', 'Tham gia vào các hoạt động chơi liên quan đến kịch bản bằng lời nói', 'Tham gia vào 3 hoạt động hoặc nhiều hơn với các hành vi chủ động (nói, thực hiện hành động, bắt chước). Chỉ giao tiếp mắt và cười là không đủ. Các ví dụ: chơi gia đình, đóng vai giáo viên hoặc cho em bé vào giường ngủ.', 10, 1),
  ('GL000262', 'DM0031', 'XH.3.11', 'Thường xuyên lôi kéo sự chú ý của người khác vào “đối tượng” bằng cách sử dụng lời nói hoặc cử chỉ/điệu bộ để bình luận, chỉ cho xem, chia sẻ và yêu cầu', 'Khởi xướng các hành vi tối thiểu 3 lần có giáo tiếp mắt. Các ví dụ lời nói (Ví dụ: “mẹ, nhìn, mèo”, “Đổ khối gỗ”, hoặc “Bố, thêm bánh”) kèm cử chỉ/điệu bộ (Ví dụ: đưa hoặc cầm đồ vật cho người lớn, chỉ vào mục).', 11, 1),
  ('GL000263', 'DM0031', 'XH.3.12', 'Phản ứng lại sự mời gọi của người khác để cùng nhau tham gia chú ý bằng cách cùng nhìn và cùng bình luận', 'Phản ứng lại trong vòng 3 giây với sự mời gọi của người lớn. Người lớn có thể lặp lại thêm một lần nữa.', 12, 1),
  ('GL000264', 'DM0031', 'XH.3.13', 'Nhận ra được các trạng thái tình cảm (vui, buồn, giận dữ, sợ hãi) từ ảnh, từ những cái khác và/hoặc qua các nét vẽ', 'Phản ứng lại trong vòng 3 giây với khởi xướng của người lớn. Người lớn có thể lặp lại thêm một lần nữa. Xác định được 2 hoặc nhiều hơn loại cảm xúc đang tác động (Ví dụ: vui, buồn, ngô nghê, sợ, ngạc nhiên). Lời nói không cần đi kèm giao tiếp mắt.', 13, 1),
  ('GL000265', 'DM0031', 'XH.3.14', 'Diễn tả được các trạng thái tình cảm từ ảnh, từ những cái khác và/hoặc qua các nét vẽ', 'Diễn tả được 2 hoặc nhiều hơn loại cảm xúc đang tác động (Ví dụ: vui, buồn, ngô nghê, sợ, ngạc nhiên). Lời nói không cần đi kèm giao tiếp mắt.', 14, 1),
  ('GL000266', 'DM0031', 'XH.3.15', 'Tự thể hiện cảm xúc trên khuôn mặt mình (vui, buồn, ngô nghê, sợ hãi)', 'Thể hiện 2 cảm xúc tác động hoặc nhiều hơn (Ví dụ: vui, buồn, ngô nghê, sợ, ngạc nhiên). Phản ứng lại không cần đi kèm giao tiếp mắt.', 15, 1),
  ('GL000267', 'DM0032', 'NT.3.1', 'Ghép các chữ cái thành tên mình', 'Ghép tất cả các chữ cái thành tên mình', 1, 1),
  ('GL000268', 'DM0032', 'NT.3.2', 'Ghép các chữ cái (Nhận diện mặt từng chữ cái)', 'Ghép 5 chữ hoặc nhiều hơn. Có thể là phản ứng lại với tín hiệu bằng lời nói của người lớn (Ví dụ: “Chữ A ở đâu?”) hoặc thực hiện một vài lần thử đầu tiên, nhưng trẻ cần ghép được độc lập ít nhất ở 5 lần thử.', 2, 1),
  ('GL000269', 'DM0032', 'NT.3.3', 'Ghép các từ (Nhận diện đồng thời cụm chữ cái tạo nên từ)', 'Ghép/phân loại 5 từ hoặc nhiều hơn. Có thể là phản ứng lại với tín hiệu bằng lời nói của người lớn (Ví dụ: “từ m-è-o ở đâu?”) hoặc thực hiện một vài thử ……..', 3, 1),
  ('GL000270', 'DM0032', 'NT.3.4', 'Ghép các số Nhận diện mặt từng số', 'Ghép/ phân loại 5 số hay nhiều hơn. Có thể phản ứng lại với tín hiệu bằng lơi nói của người lớn VD : số 6 đâu? Hay thực hiện một vài lần thử đầu tiên nhưng trẻ cần ghép được độc lập it́ nhất ở 5 lần thử.', 4, 1),
  ('GL000271', 'DM0032', 'NT.3.5', 'Nhận biết thể hiện được một số chữ cái, con số, hìng dạng và màu sắc', 'Xác định được số lượng tối thiểu 5 trong mỗi hạng mục. Có thể phản ứng lại với tín hiệu bằng lơi nói của người lớn (VD : “số 6 đâu”?, “Chỉ cho cô bút màu xanh”? Hay “Chữ cái…đâu?)”Hay thực hiện một vài lần thử đầu tiên nhưng trẻ cần ghép được độc lập it́ nhất ở 5 lần thử.', 5, 1),
  ('GL000272', 'DM0032', 'NT.3.6', 'Chơi trò liên quan đến việc nhớ ra đồ vật bị giấu', 'Xác định được ít nhất 3 đồ vật bị giấu. Người lớn thăm dò bằng cách cho trẻ xem 3 đồ vật (VD: đồng xu, quả bóng nhỏ, que) và sau đó chụp mỗi cái cốc vào từng món.. Đợi 7 giây và sau đó cho xem bản copy thứ hai của các món bị giấu (Vd : Quả bóng nhỏ và hỏi quả bóng đâu?). Phản ứng cuả trẻ có thể là lời nói “Kia” hay cử chỉ điệu bộ (Vd: Chỉ tay/ cầm cốc lên.) Giao tiếp mắt không cần thiết. Nên cho thử nhiều lần', 6, 1),
  ('GL000273', 'DM0032', 'NT.3.7', 'Phân loại các đồ vật/tranh ảnh theo 8 mục', 'Phân loại theo bộ có số lượng 3 cho đến 8 mục', 7, 1),
  ('GL000274', 'DM0032', 'NT.3.8', 'Hiểu được mối quan hệ giưã các biểu tượng về số lượng và chữ số từ 1->5', 'Hiểu được mối quan hệ cả bằng lời nói (VD : Đếm đến 5 đồ vật) hay bằng cử chỉ điệu bộ (VD : Chạm vào hay ghép nhóm 5 đồ vật)', 8, 1),
  ('GL000275', 'DM0032', 'NT.3.9', 'Đếm đúng số đối tượng từ 5 trở lên', 'Xác định được số lượng 5 đối tượng hay nhiều hơn. Người lớn có thể cho trẻ đếm những đồ vật yêu thích như kẹo,đoàn tàu và những khối gỗ. Người lớn có thể đếm mục đầu tiên để bắt đầu nhưng trẻ phải tiếp tục và tự kết thúc.', 9, 1),
  ('GL000276', 'DM0032', 'NT.3.10', 'Xâu chuỗi từ 3 tranh trở lên đúng theo trình tự và diễn tả lại trình tự bằng cách sử dụng các từ “ đầu tiên, sau đó”', 'Có thể trong phản ứng với tín hiệu băng lời nói của người lớn Vd: Tiếp theo làm gì . Trẻ cần tự xâu chuỗi và kể lại khi được hỏi “ Kể cho cô về cái đó” đối với 3 chuỗi tranh khác nhau', 10, 1),
  ('GL000277', 'DM0033', 'C.3.1', 'Chơi trò xây dựng bao gồm một chuỗi các chủ đề chơi phức tạp, kết hợp sử dụng các đồ vật đa dạng Vd: Xe tải trên đường, viên gạch xây nhà, xâu hạt thành vòng cổ', 'Xây dựng được ba chủ đề chơi hay nhiều hơn', 1, 1),
  ('GL000278', 'DM0033', 'C.3.2', 'Kết nối từ 3 hành động có liên quan trở lên trong trò chơi xâu chuỗi', 'Vd: Xây dựng đường ray, đẩy tàu hoả và đâm vào tàu hay chia đất nặn, dụng cụ cắt theo hình dạng lấy hình cắt ra.', 2, 1),
  ('GL000279', 'DM0033', 'C.3.3', 'Thực hiện từ 2 hành động kết nối với nhau trở lên khi chơi với búp bê hay thú nhồi bông khi được hướng dẫn', 'Vd: Rót nước và cho bé uống, lấy chăn và cho búp bê lên giường đi ngủ hay đặt thú bông lên xe và đẩy thú bông đi.', 3, 1),
  ('GL000280', 'DM0033', 'C.3.4', 'Xếp đặt chỗ phù hợp lên các mô hình đồ vật, phương tiện thu nhỏ một cách thích hợp', 'Xếp đặt chỗ trong bối cảnh phù hợp khi chơi. Vd: Ba ngồi trong ghế bành đề xem tivi, mẹ ngồi trong xe để đi chợ.', 4, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000281', 'DM0033', 'C.3.5', 'Thực hiện các hành động với búp bê hay thú đồ chơi một cách tự phát', 'Thực hiện ba hành động trở lên không cần người lớn nhắc.', 5, 1),
  ('GL000282', 'DM0033', 'C.3.6', 'Sắp xếp các đồ dùng theo chủ đề chơi', 'Chỉ dùng 2 (hoặc nhiều hơn) số lần nhắc trong 3 (hoặc nhiều hơn) chủ đề chơi khác nhau. Vd: sắp xếp nĩa và cho em bé ăn, đặt mũ lên đầu của mình và người khác để chơi mặc quần áo.', 6, 1),
  ('GL000283', 'DM0034', 'VDT.3.1', 'Hoàn thiện bảng ghép với 5-6 miếng ăn khớp nhau', 'Đã giải thích', 1, 1),
  ('GL000284', 'DM0034', 'VDT.3.2', 'Bắt chước vẽ hình tròn, chữ thập, hình vuông, đường chéo', 'Bắt chước mỗi hình ở tối thiểu một lần. Người lớn làm mẫu và có thể sử dụng lời nhắc Vd: “vẽ đi”', 2, 1),
  ('GL000285', 'DM0034', 'VDT.3.3', 'Bắt chước và xây dựng các cấu trúc bằng khối khác nhau có sử dụng đa dạng các vật liệu xây dựng các khối, Lego, các đồ chơi Tinker', 'Sử dụng 5 khối hay nhiều hơn để xây dựng 3 cấu trúc khác nhau hay nhiều hơn .', 3, 1),
  ('GL000286', 'DM0034', 'VDT.3.4', 'Xâu qua lỗ trong mảnh xâu hình', 'Xâu qua 3 lỗ hay nhiều hơn.  Người lớn có thể dùng hình thức nhắc bằng lời hoặc làm mẫu lần đầu.', 4, 1),
  ('GL000287', 'DM0034', 'VDT.3.5', 'Di/ tô theo các đường thẳng, đường cong bằng ngón tay hay các dụng cụ tập viết.', 'Di/ tô theo các đường thẳng, đường cong bằng ngón tay và dụng cụ vẽ. Người lớn có thể làm mẫu.', 5, 1),
  ('GL000288', 'DM0034', 'VDT.3.6', 'Sử dụng các kẹp hay cái nĩa để thả thả nhặt đồ vật.', 'Biết dùng 2 (hoặc nhiều hơn) loại dụng cụ để kẹp và thả 2 (hoặc nhiều hơn) đồ vật. Vd: Sử dụng một thià to để xúc/ thả một miếng đồ ăn hay cái kẹp để kẹp lên', 6, 1),
  ('GL000289', 'DM0034', 'VDT.3.7', 'Di/tô theo các hình dạng khác nhau', 'Di/tô theo các 3 hình dạng khác nhau hay nhiều hơn Vd : Hình vuông, hình tròn, hình tam giác, hình chữ nhật', 7, 1),
  ('GL000290', 'DM0034', 'VDT.3.8', 'Sử dụng kéo ngón tay ở vị trí/tư thế thích hợp và dùng tay còn lại để giữ và xoay giấy', 'Cắt không cần theo một đường nhưng phải cắt giấy ra làm hai. Người lớn có làm mẫu cách cầm cầm kéo và cắt dọc giấy.', 8, 1),
  ('GL000291', 'DM0034', 'VDT.3.9', 'Cắt theo đường kẻ - đường thẳng và cong', 'Cắt dọc chính xác theo đường. Người lớn có thể làm mẫu ở lần thử đầu tiên.', 9, 1),
  ('GL000292', 'DM0034', 'VDT.3.10', 'Tạo sản phẩm nghệ thuật gồm hai bước cắt và dán, đóng dấu và chấm mực', 'Người lớn có thể gợi ý bằng lời. Vd: làm cái này sau đó làm cái này hay thể hiện các bước làm trong lần thử đầu tiên.', 10, 1),
  ('GL000293', 'DM0034', 'VDT.3.11', 'Sử dụng các công cụ để tạo ra hìng dạng của đất nặn, từ đó sáng tạo ra nhiều chủ đề chơi.', 'Thực hiện ba chủ đề chơi + dùng được 2 dụng cụ (hay nhiều hơn). Vd: vo tròn đất nặn, kẹp đất và cắt bằng dao để tạo hình con rắn; hoặc tạo hình cầu và dùng nĩa để tưởng tượng là đang ăn,…', 11, 1),
  ('GL000294', 'DM0035', 'VDTH.3.1', 'Đi xe ba bánh (đạp xe, chỉnh hướng, giữ đúng hướng)', 'Đạp pê đan và tự lái theo một đường nhất định', 1, 1),
  ('GL000295', 'DM0035', 'VDTH.3.2', 'Đá và giữ thăng bằng tốt', 'Đá không cần bám vào đồ vật, không vấp ngã. Thực hiện được ba lần (hoặc nhiều hơn)', 2, 1),
  ('GL000296', 'DM0035', 'VDTH.3.3', 'Sử dụng các thiết bị ở sân chơi có người lớn hỗ trợ', 'Vd : Đu quay, ván trượt nhỏ, ván bập bênh, xà đu,..', 3, 1),
  ('GL000297', 'DM0035', 'VDTH.3.4', 'Chơi trò đuổi bắt với người lớn và các bạn, chạy dễ dàng, thay đổi hướng, giữ thăng bằng tốt', 'Chơi tối thiểu năm phút', 4, 1),
  ('GL000298', 'DM0035', 'VDTH.3.5', 'Bắt chước các hành động vận động thô với chuyển động theo bài hát', 'Năm hành động hay nhiều hơn trong tối thiểu ba bài hát', 5, 1),
  ('GL000299', 'DM0035', 'VDTH.3.6', 'Ném thấp tay vào mục tiêu', 'Tối thiểu ba lần, không cần trúng đích hoàn hảo', 6, 1),
  ('GL000300', 'DM0035', 'VDTH.3.7', 'Nhảy chụm hai chân về phiá trước', 'Nhảy về phía trước ba lần hay nhiều hơn', 7, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000301', 'DM0035', 'VDTH.3.8', 'Nhảy lò cò', 'Nhảy lò cò bằng một chân ít nhất một lần có thể vịn vào người/đồ vật khác. Không ngã.', 8, 1),
  ('GL000302', 'DM0036', 'TL.3.1', 'Sử dụng thià dĩa và li một cách gọn gàng và không đổ', 'Không cần cầm đúng', 1, 1),
  ('GL000303', 'DM0036', 'TL.3.2', 'Cư xử phù hợp trong nhà hàng', 'Không có hành vi nghiêm trọng nào Vd: Ném, bò dưới gầm bàn, chạy đi. Thỉnh thoảng gây ôǹ ào nhưng có thể thu hút vào hoạt động khác Vd: Vẽ trên bàn, chơi với đồ chơi', 2, 1),
  ('GL000304', 'DM0036', 'TL.3.3', 'Biết sử dụng độc lập hệ thống các biểu tượng (icon/symbol) để lựa chọn, thực hiện các hoạt động (nếu ở nhà và ở trường có yêu cầu)', 'Biết tìm các biểu tượng thích hợp trong sách, hoàn thành hoạt động mà không cần sự trợ giúp (>80%). Nếu nhà trường không yêu cầu vấn đề này, bỏ qua.', 3, 1),
  ('GL000305', 'DM0036', 'TL.3.4', 'Tự mang đồ dùng cá nhân vào hay lấy ra từ xe, trường hay nhà', 'Vd : Ba lô, áo khoác,....', 4, 1),
  ('GL000306', 'DM0036', 'TL.3.5', 'Mở và khoá balô một cách độc lập, cho vào và lấy ra khi được yêu cầu', 'cho vào và lấy ra khi được yêu cầu', 5, 1),
  ('GL000307', 'DM0036', 'TL.3.6', 'Mặc và cởi quần áo phù hợp', 'Tự kéo khóa và đóng cúc', 6, 1),
  ('GL000308', 'DM0037', 'TL.3.7', 'Sử dụng toilet độc lập, tất cả các bước', 'Có thể yêu cầu trợ giúp rửa tay nếu không thể với tới bồn', 1, 1),
  ('GL000309', 'DM0037', 'TL.3.8', 'Tự thao tác với trang phục khi đi vệ sinh nhưng không cần kéo khóa/gài nút', 'Kéo đồ lót và quần lên xuống, người lớn có thể giúp cầm quần áo nhưng trẻ phải tự kéo lên xuống', 2, 1),
  ('GL000310', 'DM0037', 'TL.3.9', 'Rửa tay một cách độc lập', 'Mở/ đóng vòi, xoa tay xà bông và lau khô tay. Có thể cần phải nhắc.', 3, 1),
  ('GL000311', 'DM0037', 'TL.3.10', 'Lau mặt bằng khăn ấm khi đưa khăn cho trẻ', 'Đưa khăn lên mặt và lau. Có thể cần phải nhắc.', 4, 1),
  ('GL000312', 'DM0037', 'TL.3.11', 'Chải tóc bằng lược', 'Có thể cần phải nhắc.', 5, 1),
  ('GL000313', 'DM0037', 'TL.3.12', 'Che miệng khi ho và hắt xì', 'Có thể cần phải nhắc.', 6, 1),
  ('GL000314', 'DM0037', 'TL.3.13', 'Tắm và lau khô, có thể cần hỗ trợ tích cực khi', 'Hỗ trợ: cung cấp khăn, dầu gội, bỏ dầu gội/sữa tắm lên khăn. Trẻ tự lau/chà người và lau khô.', 7, 1),
  ('GL000315', 'DM0037', 'TL.3.14', 'Đánh răng bằng bàn chải, it́ nhất vài đường', 'Người lớn có thể bôi kem vào bàn chải', 8, 1),
  ('GL000316', 'DM0038', 'TL.3.15', 'Cho vật nuôi ăn uống', 'Cho đồ ăn, nước uống vô tô và đem tới vật nuôi. Người lớn có thể giúp mở gói đồ ăn, đo lường và nhắc.', 1, 1),
  ('GL000317', 'DM0038', 'TL.3.16', 'Giúp đỡ dọn bàn', 'Dọn dẹp ít nhất 2 hay nhiều đồ vật để vào bồn rửa. Có thể cần phải nhắc.', 2, 1),
  ('GL000318', 'DM0038', 'TL.3.17', 'Giúp đỡ dọn dẹp máy rửa chén', 'Dọn dẹp ít nhất 5 hay nhiều đồ vật. Người lớn chỉ đồ nào đặt ở đâu. Dọn dẹp ít nhất 2 hay nhiều đồ vật để vào bồn rửa. Có thể cần phải nhắc.', 3, 1),
  ('GL000319', 'DM0038', 'TL.3.18', 'Xếp quần áo sạch vào tủ', 'Đăṭ 3 món quần áo hay nhiều hơn gọn gàng vào tủ. Không cần biết gấp quần áo. Có thể cần phải nhắc.', 4, 1),
  ('GL000320', 'DM0038', 'TL.3.19', 'Dọn vật dụng cá nhân khi được yêu cầu', 'Cầm vật dụng cá nhân cất đi khi được yêu cầu. Để đồ vật đúng chỗ. Có thể cần phải nhắc.', 5, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000321', 'DM0039', 'GTN.4.1', 'Hiểu được nhiều khái niệm về mối liên hệ thể chất.', 'Cầm lên, đưa cho, chỉ tay hoặc chọn 1 trong 2 đồ vật đúng cho người lớn. Trẻ xác định đúng 5 khái niệm khác nhau. VD: nóng/lạnh, hết/đầy, ướt/khô, cứng/mềm, nặng/nhẹ, cao/thấp, dài/ngắn, lớn/bé.', 1, 1),
  ('GL000322', 'DM0039', 'GTN.4.2', 'Lấy ra được 10-15 đồ vật bằng cách sử dụng 2-3 dấu hiệu khác nhau (VD: kích cỡ, số lượng, màu sắc, nhãn mác).', 'Cầm lên, đưa, chỉ hoặc cho người lớn xem đồ vật đúng (VD: người lớn hỏi "Con có thể lấy cho cô chiếc bút màu xanh không?" và trẻ đưa đúng đồ.', 2, 1),
  ('GL000323', 'DM0039', 'GTN.4.3', 'Hiểu được các đại từ liên quan đến giới tính.', 'Trẻ cầm lên, đưa, chỉ hoặc cho xem nhân vật nam hoặc nữ, tượng hoặc người thực phản ứng lại một cách phù hợp với những chỉ dẫn gồm "anh ấy hay cô ấy". VD: "Đặt cậu bé vào ô tô" hoặc "Cô ấy muốn một vài cây kem". Trẻ cần vượt qua ít nhất một đại từ về giới tính.', 3, 1),
  ('GL000324', 'DM0039', 'GTN.4.4', 'Hiểu được các đại từ so sánh: lớn hơn, ngắn hơn, nhỏ hơn, nhất, ít nhất, một vài, nhiều,…', 'Cầm lên, đưa chỉ tay hoặc cho xem đồ vật đúng cho người lớn trong một nhóm có 4-5 vật để lựa chọn. Để vượt qua, trẻ cần phải hiểu được 3 nhóm so sánh hoặc nhiều hơn.', 4, 1),
  ('GL000325', 'DM0039', 'GTN.4.5', 'Hiểu được mối liên hệ không gian bao gồm các đồ vật và các giới từ đằng sau, đằng trước.', 'Trẻ hiểu được những khái niệm: bên cạnh, đằng sau, ở phía trước bằng cách để đồ vật đúng vị trí hoặc nhìn vào địa điểm đúng khi được hướng dẫn. (VD: Nhìn đằng sau ghế).', 5, 1),
  ('GL000326', 'DM0039', 'GTN.4.6', 'Hiểu được các khái niệm phủ định (VD: hộp không có bóng, cậu bé không ngồi).', 'Cầm lên, đưa, chỉ tay hoặc cho xem các đồ vật dùng để xác định đúng để xác định đúng sự thiếu vắng một đồ vật nào đó (chiếc bát không có quả sơ ri) hoặc tìm bạn không đội mũ) hoặc một hành động bị thiếu (người đang không ngủ).', 6, 1),
  ('GL000327', 'DM0039', 'GTN.4.7', 'Hiểu được sở hữu của mối liên hệ trong tổng thể.', 'Với đồ vật và tranh ảnh, trẻ chỉ tay hoặc cho xem bộ phận nào đó khi được yêu cầu (VD: mũi con thỏ, bánh xe, cánh cửa xe ô tô).', 7, 1),
  ('GL000328', 'DM0039', 'GTN.4.8', 'Thể hiện sự quan tâm với các câu chuyện ngắn và hiểu được các phần của câu chuyện tương ứng với các câu hỏi đơn giản (cái gì và ai).', 'Trẻ lắng nghe những câu chuyện đơn giản khi người lớn đọc (5 trang). Trẻ thể hiện sự quan tâm chú ý bằng cách cùng người lớn nhìn vào cuốn sách và phản ứng lại một cách chính xác câu hỏi ai/cái gì bằng lời hoặc bằng chỉ tay. Cuối cùng trả lời được 2-3 câu hỏi.', 8, 1),
  ('GL000329', 'DM0039', 'GTN.4.9', 'Trả lời câu hỏi "có/không" để nhận dạng .', 'Trả lời đúng bằng cách phát âm hoặc gật/lắc đầu khi người lớn hỏi "Có phải là….?" hoặc "Tên con là Nam phải không?".', 9, 1),
  ('GL000330', 'DM0039', 'GTN.4.10', 'Trả lời câu hỏi về các trạng thái thể chất.', 'Trẻ phản ứng đúng với cụm câu hỏi "Con sẽ làm gì nếu….?" cho 4 trạng thái hoặc nhiều hơn: đau, mệt, đói, khát.', 10, 1),
  ('GL000331', 'DM0039', 'GTN.4.11', 'Trả lời các câu hỏi về thông tin cá nhân.', 'Phản ứng đúng với 3 câu hỏi liên quan đến thông tin cá nhân hoặc nhiều hơn. Các VD: "Tên con là gì?" (Họ và tên), "Số điện thoại của nhà con là bao nhiêu?" và "Địa chỉ của nhà con là gì?".', 11, 1),
  ('GL000332', 'DM0039', 'GTN.4.12', 'Hiểu "giống" và "khác nhau".', 'Cầm lên, đưa, chỉ tay và cho xem các đồ vật/tranh ảnh đáp lại những hướng dẫn như tìm đồ vật giống nhau, và các đồ vật/tranh ảnh khác nhau.', 12, 1),
  ('GL000333', 'DM0039', 'GTN.4.13', 'Hiểu các khái niệm về số lượng.', 'Cầm lên, đưa, chỉ tay hoặc cho xem đồ vật hoặc tranh ảnh phản ứng lại với các từ chỉ số lượng : một, một vài, tất cả, một ít, hầu hết. Cần phải vượt qua được hết mới đạt.', 13, 1),
  ('GL000334', 'DM0039', 'GTN.4.14', 'Nhận diện được đặc điểm của các đồ vật.', 'Cầm lên, đưa, chỉ tay hoặc cho xem đồ vật với đặc điểm như người lớn thể hiện. VD: người lớn nói "Đưa cho cô con chó có tai dài" và trẻ chỉ đúng. Các đặc điểm bao gồm kích cỡ, hình dáng, chất liệu, trạng thái thể chất (lỏng/rắn, mềm/cứng, nhũn/dai,…) Vượt qua nếu hiểu được 10-15 đặc điểm.', 14, 1),
  ('GL000335', 'DM0039', 'GTN.4.15', 'Trả lời các câu hỏi liên quan đến các đặc điểm của của đồ vật/tranh ảnh.', 'Trẻ hiểu các đặc điểm đồ vật bao gồm: màu sắc, hình dạng, kích cỡ hoặc chức năng, cái màu xanh, cái nào hình tròn, cái nào to, cái nào dùng để ăn.', 15, 1),
  ('GL000336', 'DM0039', 'GTN.4.16', 'Hiểu việc đã xảy ra trong quá khứ và việc sẽ xảy ra trong tương lai.', 'Trẻ xác định được việc đã xảy ra trong quá khứ. "Chỉ cho cô bạn trai đã nhảy" và xác định việc sắp xảy ra trong tương lai. Hiểu và phân biệt được mốc thời gian.', 16, 1),
  ('GL000337', 'DM0039', 'GTN.4.17', 'Hiểu thể bị động.', 'Trẻ hiểu được thể bị động thông qua hành động với đồ vật hoặc sự lựa chọn tranh ảnh (VD: "Con chó bị quả bóng đập vào". "Cô bé bị cậu bé đuổi").', 17, 1),
  ('GL000338', 'DM0039', 'GTN.4.18', 'Hiểu các mối liên hệ thuộc thời gian.', 'Trẻ phản ứng lại chính xác với 3 hướng dẫn có liên hệ thời gian: đầu tiên/cuối cùng, trước/sau, cùng lúc.', 18, 1),
  ('GL000339', 'DM0039', 'GTN.4.19', 'Làm theo được các hướng dẫn bằng lời không có liên quan gồm 3 phần.', 'Tuân theo yêu cầu của người lớn gồm 3 phần, VD: người lớn nói "Đưa cho cô cái cốc", "Hôn con gấu", và "Đóng hộp", "Vượt qua nếu thể hiện đúng.', 19, 1),
  ('GL000340', 'DM0040', 'GTD.4.1', 'Trả lời các câu hỏi phức tạp ("Tại sao?", "Như thế nào").', 'Trẻ trả lời đúng các câu hỏi liên quan đến các khái niệm này (VD: "Tại sao chúng ta rửa tay?", "Con đánh răng như thế nào?".', 1, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000341', 'DM0040', 'GTD.4.2', 'Miêu tả các chức năng của đồ vật để trả lời câu hỏi (VD: "Con làm gì với cái thìa?).', 'Có thể mô tả chức năng của 5 đồ vật thông thường hoặc nhiều hơn bằng cách sử dụng các cụm từ đơn giản.', 2, 1),
  ('GL000342', 'DM0040', 'GTD.4.3', 'Nói câu 3-4 từ một cách nhất quán.', 'Hiểu để diễn đạt phù hợp đúng một số ngữ cảnh, các đối tác và các hoạt động.', 3, 1),
  ('GL000343', 'DM0040', 'GTD.4.4', 'Sử dụng các cụm danh từ khác nhau.', 'Trẻ kết hợp được một số từ và tạo các cụm danh từ có thể dài 4 từ, gồm các mạo từ, đại từ sở hữu, tính từ và số từ (VD: "Chú ngựa nhỏ", "Bút chì màu đỏ của con", "Chiếc xe tải này", "Hai cái bánh quy", "Hình vuông to màu đỏ").', 4, 1),
  ('GL000344', 'DM0040', 'GTD.4.5', 'Sử dụng các cụm giới từ, VD: dưới, kế tiếp, đằng sau, đằng trước.', 'Trẻ nói các giới từ như được lên danh sách ở bên để mô tả đồ vật, trả lời câu hỏi và hướng dẫn người khác cách phân bố/sắp xếp.', 5, 1),
  ('GL000345', 'DM0040', 'GTD.4.6', 'Sử dụng các động từ khác nhau đúng ngữ pháp và bối cảnh.', 'Tự giải thích. (VD: cậu bé khóc, cô ấy thích cậu ấy, cậu ấy ngã, cậu ấy đã vui vẻ, cậu ấy đang vui).', 6, 1),
  ('GL000346', 'DM0040', 'GTD.4.7', 'Thể hiện chính xác ít nhất 80%tất cả các phụ âm và các hỗn hợp nguyên âm, phụ âm trong lời nói.', 'Trẻ thể hiện chính xác được 80% âm thanh trong hội thoại, lời nói dễ hiểu với người bản xứ.', 7, 1),
  ('GL000347', 'DM0040', 'GTD.4.8', 'Miêu tả trải nghiệm hiện tại bằng cách sử dụng câu 3-4 từ.', 'Khi được hỏi, trẻ miêu tả trải nghiệm gần đây với tối thiểu là 2 thành phần (ai, cái gì, ở đâu, khi nào). VD: "Con đã làm gì vào tiệc sinh nhật của mình?", "Con nhận được quà từ bạn An".', 8, 1),
  ('GL000348', 'DM0040', 'GTD.4.9', 'Yêu cầu sự chấp nhận được theo đuổi một hoạt động nào đó.', 'Trẻ xin phép trước khi điều chỉnh cái gì đó: "Con có thể mở quạt to hơn được không?" (khi thấy nóng), "Con có thể ăn món này được không?" (hỏi xin phép người lớn). Cũng có thể khi trẻ muốn bắt đầu một hoạt động khác "Chúng ta có thể nghe nhạc được không?".', 9, 1),
  ('GL000349', 'DM0040', 'GTD.4.10', 'Sử dụng số nhiều.', 'Trẻ sử dụng từ chỉ số nhiều một cách nhất quán và tự phát (VD: vài, các, những, mấy,…).', 10, 1),
  ('GL000350', 'DM0040', 'GTD.4.11', 'Sử dụng các từ sở hữu (VD: của cô ấy, của anh ấy,…).', 'Trẻ sử dụng đều đặn những từ này.', 11, 1),
  ('GL000351', 'DM0040', 'GTD.4.12', 'Sử dụng câu diễn tả một hoạt động đã xảy ra trong quá khứ bằng cách sử dụng một số từ phù hợp (vừa, đã + động từ).', 'Trẻ sử dụng đều đặn mẫu câu này một cách tự phát và thường xuyên.', 12, 1),
  ('GL000352', 'DM0040', 'GTD.4.13', 'Sử dụng từ "một" như "1 con chó, 1 cái bàn".', 'Trẻ sử dụng những từ đó thường xuyên trong các câu và cụm từ.', 13, 1),
  ('GL000353', 'DM0040', 'GTD.4.14', 'Sử dụng các từ so sánh hơn, hơn nhất.', 'Sử dụng 5 từ đúng hoặc nhiều hơn, tốt hơn, tốt nhất, to hơn, to nhất, bé hơn, bé nhất,…', 14, 1),
  ('GL000354', 'DM0040', 'GTD.4.15', 'Sử dụng động từ ở dạng phủ định (không + động từ).', 'VD: "Con không khóc", "Con không đánh bạn ấy".', 15, 1),
  ('GL000355', 'DM0040', 'GTD.4.16', 'Sử dụng câu diễn tả hoạt động đang diễn ra (đang + động từ).', 'Diễn đạt câu mô tả hoạt động đang xảy ra "Con đang ăn bánh".', 16, 1),
  ('GL000356', 'DM0040', 'GTD.4.17', 'Sử dụng từ mô tả các trạng thái của cơ thể.', 'Trẻ sử dụng 5 từ hoặc nhiều hơn để mô tả trạng thái của bản thân. "Con đói/lạnh/khát/mệt/đau".', 17, 1),
  ('GL000357', 'DM0040', 'GTD.4.18', 'Trả lời các câu hỏi về các trạng thái thể chất: "Con làm gì khi con…….?"', 'Trẻ phản ứng đúng với 5 trạng thái hoặc nhiều hơn.', 18, 1),
  ('GL000358', 'DM0040', 'GTD.4.19', 'Sử dụng tên các nhóm để phân loại đồ vật theo nhóm cho các đồ vật quen thuộc (3 cấp độ: tên - nhóm - lớp/loại/loài).', 'VD: con cá là động vật sống dưới nước.', 19, 1),
  ('GL000359', 'DM0040', 'GTD.4.20', 'Mô tả các đặc điểm của đồ vật.', 'Trẻ có thể gọi tên 3 đặc điểm hoặc nhiều hơn của 5 đồ vật thông thường khi được hỏi "Kể cho cô về…..".', 20, 1),
  ('GL000360', 'DM0040', 'GTD.4.21', 'Sử dụng các đại từ phản thân (tự ai đó đã làm điều gì).', 'Sử dụng 2 đại từ phản thân hoặc nhiều hơn, gồm: tự tôi, tự bạn, tự anh ấy, tự cô ấy, tự ai đó, tự chúng tôi, tự chúng nó, tự họ.', 21, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000361', 'DM0040', 'GTD.4.22', 'Trả lời điện thoại một cách phù hợp.', 'Di chuyển tới chỗ điện thoại đang kêu, cầm lên và đặt vào tai, nói lời chào và nhận ra người đang gọi.', 22, 1),
  ('GL000362', 'DM0040', 'GTD.4.23', 'Tham gia vào hội thoại được người lớn khởi xướng trong 2 – 3 lượt liên quan đến các chức năng khác nhau (VD: bình luận, trả lời và yêu cầu thông tin).', 'Trẻ duy trì hội thoại bằng cách thêm các yếu tố, hỏi câu hỏi, bình luận hoặc hỏi và duy trì chủ đề xuyên suốt 2 – 3 lượt hội thoại.', 23, 1),
  ('GL000363', 'DM0040', 'GTD.4.24', 'Khởi xướng và duy trì hội thoại với chủ đề tự tạo với một người lớn.', 'Trẻ bắt đầu hội thoại với một người khác bằng một bình luận hoặc câu hỏi và duy trì chủ đề xuyên suốt tối thiểu 4 lượt hội thoại.', 24, 1),
  ('GL000364', 'DM0040', 'GTD.4.25', 'Mô tả chuỗi các hoạt động gồm từ 2 – 3 sự kiện (VD: đi thăm bà).', 'Trong phản ứng lại với một câu hỏi mở - kết (VD: “Kể cho cô về chuyến thăm bà ngoại”, trẻ sẽ miêu tả 1 hoặc 3 hoạt động hoặc sự kiện bằng cách sử dụng cụm lời nói).', 25, 1),
  ('GL000365', 'DM0040', 'GTD.4.26', 'Thể hiện “Con không biết”bằng cách nói kèm cử chỉ/điệu bộ.', 'Khi được hỏi câu hỏi mà trẻ không biết câu trả lời, trẻ phản ứng lại một cách phù hợp.', 26, 1),
  ('GL000366', 'DM0040', 'GTD.4.27', 'Yêu cầu được làm rõ nếu không hiểu.', 'Trẻ nói “Cái gì?” hoặc phản ứng tương tự khi trẻ không nghe thấy hoặc không hiểu câu bình luận, câu hỏi, hoặc hướng dẫn dành cho trẻ.', 27, 1),
  ('GL000367', 'DM0040', 'GTD.4.28', 'Tham gia vào các chủ đề khác nhau trong suốt cuộc hội thoại.', 'Trẻ khởi xướng và tham gia hội thoại theo các chủ đề khác nhau.', 28, 1),
  ('GL000368', 'DM0040', 'GTD.4.29', 'Tự sửa lời nói của mình nếu người nghe không hiểu.', 'Trẻ thể hiện các kỹ năng sửa lỗi (VD: lặp lại, nói lại cụm từ, kết hợp phát âm với cử chỉ/điệu bộ, nhấn mạnh) để làm rõ ý khi đối tác không hiểu.', 29, 1),
  ('GL000369', 'DM0040', 'GTD.4.30', 'Trả lời các câu hỏi về bản thân và về những người khác.', 'Trẻ có thể trả lời một số câu hỏi đơn giản khác nhau về bản thân và cũng có thể trả lời các câu hỏi về những người thân thuộc khác – các thành viên trong gia đình, thú cưng, bạn thân….', 30, 1),
  ('GL000370', 'DM0041', 'XH.4.1', 'Mời các bạn cùng lứa chơi.', 'Nói hoặc dùng cử chỉ/điệu bộ với bạn cùng lứa (“Lại đây chơi tàu hỏa đi”, “Hãy chơi đuổi bắt” hoặc vẫy tay với bạn).', 1, 1),
  ('GL000371', 'DM0041', 'XH.4.2', 'Sử dụng các mẫu lịch sự, kiểu như “Xin lỗi”.', 'Sử dụng một số mẫu lịch sự như “Không, cảm ơn”, “Cảm ơn”, “Rất hân hạnh”, “Xin lỗi” và “Rất tiếc”.', 2, 1),
  ('GL000372', 'DM0041', 'XH.4.3', 'Tìm kiếm những người khác để có cảm giác an toàn, thuận tiện khi ở trong một nhóm đông.', 'Khi trẻ sợ, đau, hoặc thất vọng, trẻ lại gần người lớn hoặc tiếp xúc thể chất với người lớn (ôm, ngồi vào lòng, cầm tay).', 3, 1),
  ('GL000373', 'DM0041', 'XH.4.4', 'Thể hiện các cảm xúc của bản thân một cách hợp lí.', 'Nói cảm xúc của bản thân “Tôi đang bực”.', 4, 1),
  ('GL000374', 'DM0041', 'XH.4.5', 'Biết lần lượt trong khi chơi độc lập.', 'Lần lượt với người lớn/bạn cùng lứa khi tham gia chơi mà không cần phải xác định lượt rõ ràng.', 5, 1),
  ('GL000375', 'DM0041', 'XH.4.6', 'Miêu tả một sự kiện nào đó hoặc trải nghiệm với bạn cùng lứa.', 'Kể lại một câu chuyện bằng lời nói cho một người bạn gồm tối thiểu là 3 chi tiết.', 6, 1),
  ('GL000376', 'DM0041', 'XH.4.7', 'Xác định được điều làm bản thân cảm thấy vui vẻ, buồn bã, giận dữ hay sợ hãi.', 'Nói 1 hoặc nhiều VD cho mỗi khái niệm (VD: vui, buồn, điên, sợ). VD: người lớn nói “Tại sao con buồn?” và trẻ nói “Cô ấy lấy sách của con và con buồn”.', 7, 1),
  ('GL000377', 'DM0041', 'XH.4.8', 'Xác định được cảm xúc của người khác dựa trên tình huống.', 'Trong các hoạt động đọc hoặc hội thoại, trẻ trả lời đúng khi được hỏi “Tại sao cô ấy khóc?” hoặc “Tại sao cậu bé sợ?”.', 8, 1),
  ('GL000378', 'DM0041', 'XH.4.9', 'Bắt đầu phát triển các cách giải quyết khi cảm thấy thất vọng, giận dữ hay sợ hãi.', 'Tham gia vào một hoặc nhiều cách giải quyết. VD: yêu cầu được nghỉ giải lao, yêu cầu trợ giúp, tới ôm, lấy một đồ vật yêu thích.', 9, 1),
  ('GL000379', 'DM0042', 'NT.4.1', 'Đếm thuộc lòng đến 20.', 'Đếm to từ 1 – 20 đúng theo thứ tự.', 1, 1),
  ('GL000380', 'DM0042', 'NT.4.2', 'Đếm các đồ vật tương ứng 1:1 cho đến 10.', 'Chạm hoặc chỉ tay vào tranh ảnh hoặc đồ vật trong khi đếm, chạm hoặc chỉ một lần cho mỗi số.', 2, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000381', 'DM0042', 'NT.4.3', 'Đưa “1”, “một vài”, “nhiều”, “một chút”, “tất cả”, “thêm” và “hầu hết”.', 'Cầm số đồ vật đúng cho người lớn khi được yêu cầu.', 3, 1),
  ('GL000382', 'DM0042', 'NT.4.4', 'Đưa ra số lượng đến 10.', 'Cầm số đồ vật đúng khi người lớn yêu cầu (“Đưa cho con bánh” hoặc “Mẹ có thể được hai cái gối không?”.)', 4, 1),
  ('GL000383', 'DM0042', 'NT.4.5', 'Biết các thuật ngữ về số lượng.', 'Phát âm 2 khái niệm hoặc nhiều hơn, gồm “1”, “vài” và “tất cả”.', 5, 1),
  ('GL000384', 'DM0042', 'NT.4.6', 'Biết các thuật ngữ có liên quan đến không gian.', 'Phát âm 2 khái niệm hoặc nhiều hơn, gồm bên cạnh, đằng sau và đằng trước.', 6, 1),
  ('GL000385', 'DM0042', 'NT.4.7', 'Hiểu và ghép được 5 – 10 từ/đồ vật có liên quan.', 'Ghép 5 đồ vật hoặc nhiều hơn với các từ gồm 3 – 4 chữ cái được viết ra.', 7, 1),
  ('GL000386', 'DM0042', 'NT.4.8', 'Có thể đọc được một số từ.', 'Đọc và phát âm 10 từ có 3 – 4 chữ cái hoặc nhiều hơn về các hành động và đồ vật thông thường.', 8, 1),
  ('GL000387', 'DM0042', 'NT.4.9', 'Có thể xác định được tên mình được viết cùng với 5 tên khác nhau.', 'Đưa, chỉ tay, cho xem hoặc nói chính tên mình trong nhóm 3 tên khác, trong đó có 1 tên có chữ cái đầu tiên giống với tên của trẻ.', 9, 1),
  ('GL000388', 'DM0042', 'NT.4.10', '“Đọc” các kí hiệu và biểu tượng.', 'Đề cập đến ý nghĩa của 3 kí hiệu và biểu tượng hoặc nhiều hơn. VD: kí hiệu dừng lại, đèn xanh, biểu tượng “không” nói chung.', 10, 1),
  ('GL000389', 'DM0042', 'NT.4.11', 'Xác định các số và các chữ cái.', 'Xác định hoặc thể hiện tên của tất cả các chữ cái có trong bảng chữ cái và các số từ 0 – 30.', 11, 1),
  ('GL000390', 'DM0042', 'NT.4.12', 'Đề cập sự đối lập và các điểm tương đồng.', 'Khi người lớn đề cập đến một khái niệm nào đó, trẻ nói tên khái niệm ngược lại. VD: Người lớn nói “Con chuột nhỏ, nhưng con voi thì….” Và trẻ nói “to”. Hoặc “Con chuột nhỏ, con chim cũng….” và trẻ nói “nhỏ”.', 12, 1),
  ('GL000391', 'DM0043', 'C.4.1', 'Sử dụng mô hình để mô phỏng các hành động trong các trò chơi.', 'Sử dụng các mô hình để thực hiện 5 hoặc nhiều hơn các hành động trong ít nhất 3 kịch bản chơi. VD: mẹ lái xe tới cửa hàng, anh trai đuổi bắt chị gái hoặc con chó nhỏ đang ăn.', 1, 1),
  ('GL000392', 'DM0043', 'C.4.2', 'Sử dụng vật thay thế để chơi những trò chơi tưởng tượng.', 'Sử dụng 3 vật thay thế hoặc nhiều hơn. VD: sử dụng một khối gỗ giả làm điện thoại, một ống nhỏ giả làm cái chai hoặc một hộp nhỏ giả làm ô tô.', 2, 1),
  ('GL000393', 'DM0043', 'C.4.3', 'Gọi tên hành động chơi giả vờ và biết chơi giả vờ chơi.', 'Gọi tên 10 hành động giả vờ hoặc hơn và/hoặc giả vờ chơi ít nhất 3 hành động chơi một cách tự phát hoặc phản ứng lại với các câu hỏi.', 3, 1),
  ('GL000394', 'DM0043', 'C.4.4', 'Liên hệ một cách tự phát 3 hành vi có liên quan hoặc nhiều hơn trong trò chơi chủ đề.', 'VD: rót nước, trộn thức ăn, đổ thức ăn vào bát, đặt vào trong mũ cứu hỏa, “lái” xe cứu hỏa, và nhảy ra khỏi lửa.', 4, 1),
  ('GL000395', 'DM0043', 'C.4.5', 'Hướng đối tác vào trò chơi.', 'Đưa ra tối thiểu 3 chỉ dẫn phù hợp để đối tác thực hiện trong vài khía cạnh trò chơi, thực hiện qua 2 đến 3 trò chơi.', 5, 1),
  ('GL000396', 'DM0043', 'C.4.6', 'Chơi theo kiểu một số các sự kiện (VD: tiệc sinh nhật, trò chơi bác sĩ), bao gồm cả phát âm.', 'Chơi 3 sự kiện hoặc nhiều hơn, mỗi sự kiện gồm ít nhất 3 hoạt động được gắn kết vào nhau (xem mục 4 ở trên), tương tác với người khác trong suốt hoạt động với đồ vật và khi nói.', 6, 1),
  ('GL000397', 'DM0043', 'C.4.7', 'Chơi theo chủ đề của một số câu chuyện.', 'Chơi theo chủ đề của 3 câu chuyện hoặc nhiều hơn với đối tác bằng cách sử dụng hành động và lời nói như được mô tả trong mục trên. VD: 3 chú lợn con…', 7, 1),
  ('GL000398', 'DM0043', 'C.4.8', 'Nhập vai vào nhân vật trong trò chơi đóng vai.', 'Đề cập đến vai trò (VD: “Con là mẹ”) và thực hiện các màn chơi cùng lời nói, hoạt động và cử chỉ/điệu bộ phù hợp với vai trò, có 3 hoặc nhiều hơn 3 hoán đổi vai với đối tác.', 8, 1),
  ('GL000399', 'DM0043', 'C.4.9', 'Theo sự hướng dẫn của người khác trong trò chơi.', 'Làm theo 5 hoặc nhiều hơn hướng dãn bằng lời hoặc phi ngôn ngữ của đối tác bằng cách bắt chước hành động của đối tác hoặc phản ứng lại những chỉ dẫn của đối tác.', 9, 1),
  ('GL000400', 'DM0044', 'VDT.4.1', 'Tô màu bức tranh một cách chính xác có sử dụng các màu khác nhau.', 'Trẻ tô màu chủ yếu trong hình và chọn các màu khác nhau để hoàn thành bức tranh trên giấy.', 1, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000401', 'DM0044', 'VDT.4.2', 'Bắt chước vẽ hình tam giác, các chữ cái có sử dụng dụng cụ vẽ phù hợp.', 'Trẻ sao chép hình tròn, hình vuông, hình tam giác và một số chữ cái có thể nhận dạng được.', 2, 1),
  ('GL000402', 'DM0044', 'VDT.4.3', 'Vẽ các đường thẳng, các hình và một số chữ cái, chữ số theo trí nhớ.', 'Trẻ tự vẽ một số hình dạng và chữ cái/con số có thể nhận dạng được.', 3, 1),
  ('GL000403', 'DM0044', 'VDT.4.4', 'Bắt chước và copy các chữ cái, các số và hình dạng khác nhau.', 'Trẻ thực hiện cả copy và tự vẽ 4 – 5 hình dạng, 4 – 5 chữ cái và một vài con số có thể nhận dạng được.', 4, 1),
  ('GL000404', 'DM0044', 'VDT.4.5', 'Viết tên mà không cần mẫu.', 'Tự giải thích.', 5, 1),
  ('GL000405', 'DM0044', 'VDT.4.6', 'Tô theo các hình dạng và các chữ.', 'Tự giải thích.', 6, 1),
  ('GL000406', 'DM0044', 'VDT.4.7', 'Tô màu trong những hình dạng đã được phác thảo.', 'Nhìn chung trẻ tô màu bên trong đường viền.', 7, 1),
  ('GL000407', 'DM0044', 'VDT.4.8', 'Nối các điểm chấm bằng bút vẽ.', 'Trẻ có thể tô theo các dấu chấm trong chuỗi con số.', 8, 1),
  ('GL000408', 'DM0044', 'VDT.4.9', 'Vẽ các đường thẳng để nối từ những bức tranh, các từ hoặc các hình dạng tương ứng.', 'Trẻ có thể tiếp tục ghép hoặc nối tranh ảnh của đồ vật bằng một đường thẳng (như trong sách hoạt động của bé).', 9, 1),
  ('GL000409', 'DM0044', 'VDT.4.10', 'Copy những nét vẻ đơn giản khác nhau (VD: khuôn mặt, cái cây, ngôi nhà, bông hoa).', 'Trẻ copy 5 nét vẽ hoặc nhiều hơn và tự tao 2 – 3 bức tranh có thể nhận dạng được.', 10, 1),
  ('GL000410', 'DM0044', 'VDT.4.11', 'Gập đôi giấy và cho vào phong bì.', 'Tự giải thích, theo mẫu.', 11, 1),
  ('GL000411', 'DM0044', 'VDT.4.12', 'Cắt các góc, các đường thẳng và đường cong.', 'Trẻ cắt các góc và cạnh cảu các hình dạng lớn (7.5 cm hoặc lớn hơn) bằng cách tự sử dụng kéo.', 12, 1),
  ('GL000412', 'DM0044', 'VDT.4.13', 'Cắt các hình dạng đơn giản.', 'Trẻ cắt được các hình dạng to khoảng 7.5 cm.', 13, 1),
  ('GL000413', 'DM0044', 'VDT.4.14', 'Hoàn thành một tác phẩm nghệ thuật gồm 3 bước – cắt, tô màu và dán.', 'Khi người lớn làm mẫu hoạt động, trẻ có thể xâu chuỗi hoạt động và tự hoàn thiện, mỗi bước gồm 1 kỹ năng và trẻ có thể thực hiện được một cách tự tin.', 14, 1),
  ('GL000414', 'DM0044', 'VDT.4.15', 'Sử dụng bút vẽ, con dấu, bút dầu, bút chì và tẩy để hoàn thành một hoạt động về nghệ thuật nào đó.', 'Trẻ sử dụng một số dụng cụ nghệ thuật để tạo bức tranh. Trẻ cũng có thể bắt chước mô hình của người lớn bằng cách sử dụng từng dụng cụ này.', 15, 1),
  ('GL000415', 'DM0044', 'VDT.4.16', 'Cầm bút vẽ bằng 3 ngón tay.', 'Trẻ cầm một cách nhất quán bằng 3 ngón tay.', 16, 1),
  ('GL000416', 'DM0044', 'VDT.4.17', 'Xây dựng bằng các vật liệu khác nhau theo thiết kế của riêng mình và copy những mẫu đơn giản từ tranh ảnh hoặc những mẫu 3D.', 'Trẻ thu thập các dụng cụ xây dựng để thiết kế các hình phức tạp, và cũng có thể copy các thiết kế của người khác, cả mô hình 3D lẫn tranh ảnh hoặc các hình vẽ. Trẻ có thể thể hiện 5 mô hình hoặc nhiều hơn.', 17, 1),
  ('GL000417', 'DM0044', 'VDT.4.18', 'Xếp các miếng ghép ăn khớp, trên sàn hoặc trong khay với nhau.', 'Tự giải thích.', 18, 1),
  ('GL000418', 'DM0044', 'VDT.4.19', 'Sử dụng băng keo, kẹp giấy, chìa khóa một cách phù hợp.', 'Tự sử dụng tất cả các công cụ.', 19, 1),
  ('GL000419', 'DM0045', 'VDTH.4.1', 'Chơi bắt với bóng cùng một người bạn.', 'Có thể chơi bắt bóng gồm 6 lượt hoặc nhiều hơn.', 1, 1),
  ('GL000420', 'DM0045', 'VDTH.4.2', 'Ném bóng tennis hoặc bóng rổ cho người khác có định hướng và theo cách giơ tay lên cao.', 'Tự giải thích.', 2, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000421', 'DM0045', 'VDTH.4.3', 'Sử dụng tất cả các dụng cụ trong sân chơi một cách độc lập, như: sử dụng xích đu, vòng quay ngựa gỗ.', 'Tự giải thích, đối với tất cả các dụng cụ phù hợp độ tuổi.', 3, 1),
  ('GL000422', 'DM0045', 'VDTH.4.4', 'Đá một quả bóng đang lăn.', 'Trẻ điều chỉnh thân người và đá được quả bóng.', 4, 1),
  ('GL000423', 'DM0045', 'VDTH.4.5', 'Chơi một số trò chơi với bóng: ném bóng vào giỏ, đánh bóng chày bằng gậy, bóng nhảy, chơi golf, ném túi hạt đậu.', 'Chơi 5 trò hoặc nhiều hơn với bóng.', 5, 1),
  ('GL000424', 'DM0045', 'VDTH.4.6', 'Đạp xe một cách tự tin; có thể kiểm soát được tốc độ, điều khiển và phanh.', 'Tự giải thích.', 6, 1),
  ('GL000425', 'DM0045', 'VDTH.4.7', 'Chạy nhanh và nhảy.', 'Bắt chước cả 2 và thể hiện một cách trôi chảy.', 7, 1),
  ('GL000426', 'DM0045', 'VDTH.4.8', 'Đi bộ mà không bị mất thăng bằng, đi đúng hàng, đúng lối.', 'Tự giải thích; đi bộ thoải mái và không quá chậm.', 8, 1),
  ('GL000427', 'DM0045', 'VDTH.4.9', 'Chơi những trò chơi vận động điển hình (VD: “đèn đỏ, đèn xanh”…).', 'Chơi 5 trò hoặc nhiều hơn – biết luật chơi và tham gia tích cực suốt trò chơi mà không cần nhắc nhở hoặc kèm cặp.', 9, 1),
  ('GL000428', 'DM0046', 'TL.4.1', 'Kiểm soát tất cả các bước bao gồm tự đi vệ sinh theo như mức độ phù hợp với lứa tuổi.', 'Sử dụng bô khi cần (mặc dù người lớn có thể nhắc đường tới phòng vệ sinh), tự kéo quần/đồ lót lên và xuống, xả nước và rửa tay.', 1, 1),
  ('GL000429', 'DM0046', 'TL.4.2', 'Đi vệ sinh khi có nhu cầu.', 'Tự đi vệ sinh khi cần (không cần người lớn nhắc).', 2, 1),
  ('GL000430', 'DM0046', 'TL.4.3', 'Tự rửa tay theo như mức độ phù hợp với lứa tuổi.', 'Trẻ vặn vòi nước, để tay dưới vòi nước, sử dụng xà phòng, xoa xà phòng vsof hai tay, rửa sạch xà phòng, tắt nước và lau khô tay bằng khăn.', 3, 1),
  ('GL000431', 'DM0046', 'TL.4.4', 'Tự rửa mặt bằng khăn.', 'Trong khi rửa, trẻ làm ướt khăn, sử dụng xà phòng (sữa rửa mặt) và lau mặt bằng khăn.', 4, 1),
  ('GL000432', 'DM0046', 'TL.4.5', 'Tự chải đầu bằng lược.', 'Khi người lớn bảo trẻ chải đầu, trẻ lấy lược và chải. Có thể có những ngoại lệ khó đối với mái tóc dài hoặc xoăn.', 5, 1),
  ('GL000433', 'DM0046', 'TL.4.6', 'Phối hợp tích cực khi tắm và lau khô người sau khi tắm.', 'Xoa người bằng khăn, sử dụng xà phòng và xoa khắp cơ thể . Tự lau khô, có thể cần nhắc bằng hành động.', 6, 1),
  ('GL000434', 'DM0046', 'TL.4.7', 'Tự thực hiện tất cả các bước đánh răng, mặc dù không kĩ lưỡng như người lớn.', 'Từ khi trẻ vào phòng tắm cho đến khi bàn chải và kem đánh răng được đặt lại vào chỗ thích hợp, trẻ có thể tự thực hiện được tất cả các bước.', 7, 1),
  ('GL000435', 'DM0046', 'TL.4.8', 'Tự mặc quần áo một cách nhanh chóng – cài cúc, kéo khóa.', 'Tự cài nút, mặc quần, kéo khóa một cách nhanh chóng.', 8, 1),
  ('GL000436', 'DM0046', 'TL.4.9', 'Tự xì mũi, dùng khăn giấy để xì mũi, dùng tay che khi ho hay xì mũi.', 'Khi người lớn nói “xì mũi”, trẻ lấy khăn giấy và xì mũi ra. Khi trẻ hắt hơi có lấy tay che miệng.', 9, 1),
  ('GL000437', 'DM0046', 'TL.4.10', 'Dừng lại khi ra đến đường; nhìn cả hai phía trước khi qua đường.', 'Khi đến lề đường cùng một người nào đó, trẻ tự động dừng lại, chờ đợi, nhìn và chờ cho người kia thể hiện là trẻ có thể qua đường.', 10, 1),
  ('GL000438', 'DM0046', 'TL.4.11', 'Đi bên cạnh người lớn một cách an toàn tới điểm đỗ xe, nhà hàng…', 'Trẻ đi bộ không cần cầm tay và đi sát người lớn, kiểm soát được vị trí và duy trì khoảng cách của chính bản thân.', 11, 1),
  ('GL000439', 'DM0046', 'TL.4.12', 'Trợ giúp dọn bàn.', 'Trẻ có thể tự đặt đĩa, cốc, khăn ăn và các đồ dùng khác vào đúng chỗ và ngăn nắp. người lớn có thể cần đánh dấu nơi cần đặt và cung cấp dụng cụ cho trẻ trên bàn.', 12, 1),
  ('GL000440', 'DM0046', 'TL.4.13', 'Dùng dao để phết lên thức ăn.', 'Trẻ có thể quét mứt/bơ lên bánh mì mà không cần xé bánh mì ra.', 13, 1);
INSERT INTO `goals` (`id`, `domain_id`, `code`, `name`, `description`, `display_order`, `is_active`) VALUES
  ('GL000441', 'DM0046', 'TL.4.14', 'Lau những chỗ bị đổ nước.', 'Trẻ tự khởi xướng lau chỗ nước bị đổ trên bàn.', 14, 1),
  ('GL000442', 'DM0046', 'TL.4.15', 'Rót đồ uống vào những vật chứa nhỏ hơn.', 'Trẻ có thể tự rót chất lỏng từ bình đựng vào cốc nhỏ hơn một cách gọn gàng.', 15, 1),
  ('GL000443', 'DM0046', 'TL.4.16', 'Đặt chén đĩa vào bồn hoặc máy rửa chén bát.', 'Sau bữa ăn, trẻ tự lau dọn và đặt dụng cụ vào đúng chỗ.', 16, 1),
  ('GL000444', 'DM0046', 'TL.4.17', 'Tiến hành bữa ăn phụ gồm 2 bước.', 'Lấy ra 2 thứ khác nhau từ hộp bỏ ra đĩa, đặt lên bàn. VD: dọn nộm rau, bơ và bánh, kem bơ để quét lên bánh, hỗ hợp ngũ cốc và sữa.', 17, 1),
  ('GL000445', 'DM0046', 'TL.4.18', 'Hỗ trợ các hoạt động nấu ăn, khuấy, đổ….', 'Trẻ thực hiện một số trong các bước nấu ăn như làm bánh quy, bánh kếp, bánh trứng…..', 18, 1);
