-- DENVER / ESDM - IMPORT DU LIEU DUNG SCHEMA MYSQL v6.1
-- UTF-8 (utf8mb4). Khong co CREATE TABLE, DROP TABLE hoac sua schema.
-- IMPORT MOT LAN vao DB da chay migration v6.1, CHUA co du lieu Denver tu truoc.
-- Neu du lieu ID PR0001/LV0001/DM0001/GL000001 da ton tai: KHONG chay; kiem tra file 00_kiem_tra_truoc_import.sql.
-- Neu co loi: ROLLBACK theo huong dan; KHONG bo qua loi duplicate hoac FK.
-- Khi chay nen tam dung API tao chuong trinh/muc tieu de tranh tranh chap ID.

SET NAMES utf8mb4;
USE `duong_an_v11`;

START TRANSACTION;

-- Dat lai gioi han sequence TRUOC insert, dung GREATEST de khong giam bo dem dang co.
UPDATE `catalog_id_sequences` SET `next_value` = GREATEST(`next_value`, 2) WHERE `entity_name` = 'programs';
UPDATE `catalog_id_sequences` SET `next_value` = GREATEST(`next_value`, 5) WHERE `entity_name` = 'program_levels';
UPDATE `catalog_id_sequences` SET `next_value` = GREATEST(`next_value`, 47) WHERE `entity_name` = 'domains';
UPDATE `catalog_id_sequences` SET `next_value` = GREATEST(`next_value`, 446) WHERE `entity_name` = 'goals';
UPDATE `catalog_id_sequences` SET `next_value` = GREATEST(`next_value`, 1) WHERE `entity_name` = 'specific_goals';

-- Insert cha -> con; bat loi trung khoa thay vi bo qua ngam.

-- programs: 1 ban ghi

-- program_levels: 4 ban ghi

-- domains: 46 ban ghi

-- goals: 445 ban ghi

-- specific_goals: Khong co muc tieu A/B/C trong Denver, khong chen.

COMMIT;

-- Kiem tra so dong moi nhap. Neu database co them VB, khong dem tong tat ca bang.
SELECT 'programs' AS bang, COUNT(*) AS so_dong FROM `programs` WHERE id = 'PR0001'
UNION ALL SELECT 'program_levels', COUNT(*) FROM `program_levels` WHERE program_id = 'PR0001'
UNION ALL SELECT 'domains', COUNT(*) FROM `domains` WHERE program_level_id IN ('LV0001','LV0002','LV0003','LV0004')
UNION ALL SELECT 'goals', COUNT(*) FROM `goals` WHERE domain_id BETWEEN 'DM0001' AND 'DM0046';

-- Ket qua ky vong: 1, 4, 46, 445.
